  )
}

export type HttpMethod = 'GET'|'POST'|'PUT'|'PATCH'|'DELETE'|'HEAD'|'OPTIONS'

export type TreeSortMode = 'none' | 'asc' | 'desc'

export type Collection = {
  id: string
  name: string
  baseUrl?: string
  variables?: Record<string, string>
  requests?: RequestItem[]
  folders: Folder[]
  sourceUrl?: string
  sourceType?: 'url' | 'file'
  sourceFileName?: string
}

export type Folder = {
  id: string
  name: string
  requests: RequestItem[]
  folders?: Folder[]
}

export type RequestParam = {
  name: string
  in: 'path'|'query'|'header'
  required?: boolean
  schemaType?: string
  enumValues?: Array<string | number | boolean>
  example?: any
}

export type RequestItem = {
  id: string
  name: string
  method: HttpMethod
  path: string                 // /users/{id}
  urlTemplate: string          // {{baseUrl}}/users/{id}
  params: RequestParam[]
  headers: Record<string, string>
  body?: {
    contentType: string
    example: any
  }
}

import type { Collection, Folder, HttpMethod, RequestItem, RequestParam } from '../types'
import { uid } from '../../../shared/utils/id'
import { isAbsoluteUrl, joinUrlParts } from '../../../shared/utils/url'

const METHODS: HttpMethod[] = ['GET', 'POST', 'PUT', 'PATCH', 'DELETE', 'HEAD', 'OPTIONS']

function resolveServerUrl(server: any): string | undefined {
  const url = server?.url
  if (typeof url !== 'string' || !url.trim()) return undefined

  const vars = server?.variables && typeof server.variables === 'object' ? server.variables : undefined
  if (!vars) return url.trim()

  return url.trim().replaceAll(/\{([^}]+)\}/g, (_m: string, name: string) => {
    const v = (vars as any)[name]
    const def = v?.default
    if (typeof def === 'string') return def
    const enum0 = Array.isArray(v?.enum) ? v.enum[0] : undefined
    if (typeof enum0 === 'string') return enum0
    return `{${name}}`
  })
}

function pickSuggestedBaseUrl(spec: any, sourceOrigin?: string): string | undefined {
  const first = Array.isArray(spec?.servers) ? spec.servers[0] : undefined
  const resolved = resolveServerUrl(first)
  if (!resolved) return undefined

  if (isAbsoluteUrl(resolved)) return resolved.replace(/\/+$/, '')

  const rel = (resolved.startsWith('/') ? resolved : `/${resolved}`).replace(/\/+$/, '')
  if (sourceOrigin) return `${sourceOrigin.replace(/\/+$/, '')}${rel}`.replace(/\/+$/, '')
  return rel
}

function opDisplayName(method: string, path: string, op: any): string {
  return op?.summary || op?.operationId || `${method.toUpperCase()} ${path}`
}

function collectParams(op: any, pathItem?: any): RequestParam[] {
  const pathParams: any[] = Array.isArray(pathItem?.parameters) ? pathItem.parameters : []
  const opParams: any[] = Array.isArray(op?.parameters) ? op.parameters : []
  const merged = [...pathParams, ...opParams]

  const byKey = new Map<string, RequestParam>()
  for (const p of merged) {
    if (!p || (p.in !== 'path' && p.in !== 'query' && p.in !== 'header')) continue
    if (typeof p.name !== 'string' || !p.name.trim()) continue
    const key = `${p.in}:${p.name}`
    const enumRaw = p.schema?.enum ?? p.enum
    const enumValues =
      Array.isArray(enumRaw) && enumRaw.length
        ? enumRaw.filter((v: any) => typeof v === 'string' || typeof v === 'number' || typeof v === 'boolean')
        : undefined
    byKey.set(key, {
      name: p.name,
      in: p.in,
      required: !!p.required,
      schemaType: p.schema?.type || p.type,
      enumValues,
      example: p.example ?? p.schema?.example,
    })
  }

  return Array.from(byKey.values())
}

function exampleFromSchema(schema: any, depth = 0): any {
  if (!schema || typeof schema !== 'object') return undefined
  if (depth > 6) return undefined

  if (schema.example !== undefined) return schema.example
  if (schema.default !== undefined) return schema.default
  if (schema.const !== undefined) return schema.const
  if (Array.isArray(schema.enum) && schema.enum.length) return schema.enum[0]

  const type = schema.type

  if (type === 'array' || schema.items) {
    const itemEx = exampleFromSchema(schema.items, depth + 1)
    return itemEx === undefined ? [] : [itemEx]
  }

  if (type === 'object' || schema.properties) {
    const props = schema.properties && typeof schema.properties === 'object' ? schema.properties : {}
    const out: Record<string, any> = {}
    for (const [k, v] of Object.entries(props)) {
      const ex = exampleFromSchema(v, depth + 1)
      if (ex !== undefined) out[k] = ex
    }
    return out
  }

  if (type === 'integer' || type === 'number') return 0
  if (type === 'boolean') return false
  if (type === 'string') return ''

  return undefined
}

function buildBody(op: any) {
  const rb = op?.requestBody
  const content = rb?.content
  if (!content || typeof content !== 'object') return undefined

  function pickContentType(): string | undefined {
    const keys = Object.keys(content)
    if (!keys.length) return undefined
    if ((content as any)['application/json']) return 'application/json'
    const jsonLike = keys.find(k => k.toLowerCase().includes('json'))
    if (jsonLike) return jsonLike
    return keys[0]
  }

  const ct = pickContentType()
  if (!ct) return undefined

  const media = (content as any)[ct]
  const exFromExamples = media?.examples?.[Object.keys(media.examples || {})[0]]?.value
  const schemaEx = media?.schema?.example ?? media?.schema?.default
  const ex: any = media?.example ?? exFromExamples ?? schemaEx ?? exampleFromSchema(media?.schema)

  if (ex !== undefined) return { contentType: ct, example: ex }
  return { contentType: ct, example: ct.toLowerCase().includes('json') ? {} : '' }
}

export function buildCollectionFromV3(spec: any, name = 'Imported API', sourceOrigin?: string): Collection {
  const baseUrl = pickSuggestedBaseUrl(spec, sourceOrigin)

  const folderMap = new Map<string, Folder>()

  const paths = spec?.paths || {}
  for (const path of Object.keys(paths)) {
    const pathItem = paths[path]
    for (const m of Object.keys(pathItem)) {
      const method = m.toUpperCase() as HttpMethod
      if (!METHODS.includes(method)) continue

      const op = pathItem[m]
      const tags: string[] = Array.isArray(op?.tags) && op.tags.length ? op.tags : ['default']

      const req: RequestItem = {
        id: uid('req'),
        name: opDisplayName(method, path, op),
        method,
        path,
        urlTemplate: joinUrlParts('{{baseUrl}}', path),
        params: collectParams(op, pathItem),
        body: buildBody(op),
        headers: {},
}

      if (req.body?.contentType) {
        req.headers = { ...req.headers, 'Content-Type': req.body.contentType }
      }

      for (const tag of tags) {
        if (!folderMap.has(tag)) {
          folderMap.set(tag, { id: uid('folder'), name: tag, requests: [], folders: [] })
        }
        folderMap.get(tag)!.requests.push(req)
      }
    }
  }

  return {
    id: uid('col'),
    name,
    baseUrl,
    folders: Array.from(folderMap.values()).sort((a, b) => a.name.localeCompare(b.name)),
  }
}

const RUF_MIME_FOLDER = 'application/x-ruf-folder'
const RUF_MIME_REQUEST = 'application/x-ruf-request'
const RUF_MIME_COLLECTION = 'application/x-ruf-collection'
const RUF_MIME_WORKSPACE_FOLDER = 'application/x-ruf-workspace-folder'

const RUF_TEXT_PREFIX = 'ruf-dnd:'

type DraggedFolder = { collectionId: string, folderId: string }
type DraggedRequest = { collectionId: string, requestId: string }
type DraggedCollection = { collectionId: string }
type DraggedWorkspaceFolder = { workspaceFolderId: string }

type DraggedAny =
  | ({ kind: 'folder' } & DraggedFolder)
  | ({ kind: 'request' } & DraggedRequest)
  | ({ kind: 'collection' } & DraggedCollection)
  | ({ kind: 'workspace-folder' } & DraggedWorkspaceFolder)

function setFallbackText(dt: DataTransfer, payload: DraggedAny) {
  dt.setData('text/plain', `${RUF_TEXT_PREFIX}${JSON.stringify(payload)}`)
}

function readFallbackText(dt: DataTransfer): DraggedAny | null {
  try {
    const raw = dt.getData('text/plain')
    if (!raw?.startsWith(RUF_TEXT_PREFIX)) return null
    const parsed = JSON.parse(raw.slice(RUF_TEXT_PREFIX.length)) as any
    const kind = parsed?.kind
    if (kind !== 'folder' && kind !== 'request' && kind !== 'collection' && kind !== 'workspace-folder') return null
    return parsed as DraggedAny
  } catch {
    return null
  }
}

export function setDraggedFolder(dt: DataTransfer, payload: DraggedFolder) {
  dt.effectAllowed = 'move'
  const full: DraggedAny = { kind: 'folder', ...payload }
  dt.setData(RUF_MIME_FOLDER, JSON.stringify(full))
  setFallbackText(dt, full)
}

export function setDraggedRequest(dt: DataTransfer, payload: DraggedRequest) {
  dt.effectAllowed = 'move'
  const full: DraggedAny = { kind: 'request', ...payload }
  dt.setData(RUF_MIME_REQUEST, JSON.stringify(full))
  setFallbackText(dt, full)
}

export function setDraggedCollection(dt: DataTransfer, payload: DraggedCollection) {
  dt.effectAllowed = 'move'
  const full: DraggedAny = { kind: 'collection', ...payload }
  dt.setData(RUF_MIME_COLLECTION, JSON.stringify(full))
  setFallbackText(dt, full)
}

export function readDraggedFolder(dt: DataTransfer): DraggedFolder | null {
  try {
    const raw = dt.getData(RUF_MIME_FOLDER)
    if (!raw) {
      const fb = readFallbackText(dt)
      if (fb?.kind !== 'folder') return null
      const collectionId = typeof fb?.collectionId === 'string' ? fb.collectionId : ''
      const folderId = typeof fb?.folderId === 'string' ? fb.folderId : ''
      if (!collectionId || !folderId) return null
      return { collectionId, folderId }
    }
    const parsed = JSON.parse(raw) as any
    const collectionId = typeof parsed?.collectionId === 'string' ? parsed.collectionId : ''
    const folderId = typeof parsed?.folderId === 'string' ? parsed.folderId : ''
    if (!collectionId || !folderId) return null
    return { collectionId, folderId }
  } catch {
    return null
  }
}

export function readDraggedRequest(dt: DataTransfer): DraggedRequest | null {
  try {
    const raw = dt.getData(RUF_MIME_REQUEST)
    if (!raw) {
      const fb = readFallbackText(dt)
      if (fb?.kind !== 'request') return null
      const collectionId = typeof fb?.collectionId === 'string' ? fb.collectionId : ''
      const requestId = typeof fb?.requestId === 'string' ? fb.requestId : ''
      if (!collectionId || !requestId) return null
      return { collectionId, requestId }
    }
    const parsed = JSON.parse(raw) as any
    const collectionId = typeof parsed?.collectionId === 'string' ? parsed.collectionId : ''
    const requestId = typeof parsed?.requestId === 'string' ? parsed.requestId : ''
    if (!collectionId || !requestId) return null
    return { collectionId, requestId }
  } catch {
    return null
  }
}

export function readDraggedCollection(dt: DataTransfer): DraggedCollection | null {
  try {
    const raw = dt.getData(RUF_MIME_COLLECTION)
    if (!raw) {
      const fb = readFallbackText(dt)
      if (fb?.kind !== 'collection') return null
      const collectionId = typeof fb?.collectionId === 'string' ? fb.collectionId : ''
      if (!collectionId) return null
      return { collectionId }
    }
    const parsed = JSON.parse(raw) as any
    const collectionId = typeof parsed?.collectionId === 'string' ? parsed.collectionId : ''
    if (!collectionId) return null
    return { collectionId }
  } catch {
    return null
  }
}

export function setDraggedWorkspaceFolder(dt: DataTransfer, payload: DraggedWorkspaceFolder) {
  dt.effectAllowed = 'move'
  const full: DraggedAny = { kind: 'workspace-folder', ...payload }
  dt.setData(RUF_MIME_WORKSPACE_FOLDER, JSON.stringify(full))
  setFallbackText(dt, full)
}

export function readDraggedWorkspaceFolder(dt: DataTransfer): DraggedWorkspaceFolder | null {
  try {
    const raw = dt.getData(RUF_MIME_WORKSPACE_FOLDER)
    if (!raw) {
      const fb = readFallbackText(dt)
      if (fb?.kind !== 'workspace-folder') return null
      const workspaceFolderId = typeof fb?.workspaceFolderId === 'string' ? fb.workspaceFolderId : ''
      if (!workspaceFolderId) return null
      return { workspaceFolderId }
    }
    const parsed = JSON.parse(raw) as any
    const workspaceFolderId = typeof parsed?.workspaceFolderId === 'string' ? parsed.workspaceFolderId : ''
    if (!workspaceFolderId) return null
    return { workspaceFolderId }
  } catch {
    return null
  }
}

