  getDbConnectionStringPreview,
  getDbFormStateFromEnv,
  hasDbConfigInEnv,
  isDbEnvKey,
  mergeDbIntoVariables,
  runDbConnectionTest,
} from '../utils/dbConnection'
import type { DbType, PgSslMode } from '../utils/dbConnection'

type HeaderRow = { key: string; value: string }
type VariableRow = { key: string; value: string }

function normalizeVarName(raw: string) {
  return raw.trim().replaceAll(/\s+/g, '')
}

export function EnvironmentSettings(props: {
  open: boolean
  collectionName: string
  env: Environment
  onSave: (env: Environment) => void
  onClose: () => void
}) {
  const dialogRef = useRef<HTMLDialogElement | null>(null)
  const dbTypeMenuWrapRef = useRef<HTMLDivElement | null>(null)
  const dbSslModeMenuWrapRef = useRef<HTMLDivElement | null>(null)

  function ensureTrailingEmptyRow<T extends { key: string; value: string }>(rows: T[]) {
    if (rows.length === 0) return [{ key: '', value: '' } as T]
    const last = rows[rows.length - 1]
    if (last.key.trim() || last.value) return [...rows, { key: '', value: '' } as T]
    return rows
  }

  function shouldHideVariableKeyFromVariablesList(key: string) {
    return isDbEnvKey(key)
  }

  const [baseUrlRow, setBaseUrlRow] = useState<VariableRow>({
    key: props.env.baseUrlKey,
    value: props.env.variables[props.env.baseUrlKey] ?? '',
  })
  const [variablesRows, setVariablesRows] = useState<VariableRow[]>(
    ensureTrailingEmptyRow(
      Object.entries(props.env.variables)
        .filter(([k]) => k !== props.env.baseUrlKey && k !== 'scheme' && !shouldHideVariableKeyFromVariablesList(k))
        .map(([k, v]) => ({ key: k, value: v })),
    ),
  )

  const [headersRows, setHeadersRows] = useState<HeaderRow[]>(
    ensureTrailingEmptyRow(Object.entries(props.env.headers).map(([k, v]) => ({ key: k, value: v }))),
  )

  const initialDb = useMemo(() => getDbFormStateFromEnv(props.env), [props.env])
  const [dbType, setDbType] = useState<DbType>(() => initialDb.type)
  const [dbSslMode, setDbSslMode] = useState<PgSslMode>(() => initialDb.sslmode)
  const [dbHost, setDbHost] = useState(() => initialDb.host)
  const [dbPort, setDbPort] = useState(() => initialDb.port)
  const [dbDatabase, setDbDatabase] = useState(() => initialDb.database)
  const [dbUsername, setDbUsername] = useState(() => initialDb.username)
  const [dbPassword, setDbPassword] = useState(() => initialDb.password)
  const [dbShowPassword, setDbShowPassword] = useState(false)
  const [dbTypeMenuOpen, setDbTypeMenuOpen] = useState(false)
  const [dbSslModeMenuOpen, setDbSslModeMenuOpen] = useState(false)
  const [dbAccordionOpen, setDbAccordionOpen] = useState(() => hasDbConfigInEnv(props.env))
  const [dbTestInFlight, setDbTestInFlight] = useState(false)
  const [dbTestError, setDbTestError] = useState<string | null>(null)
  const [dbTestLog, setDbTestLog] = useState<string | null>(null)
  const [dbTestOkMs, setDbTestOkMs] = useState<number | null>(null)
  const dbTestOkResetTimerRef = useRef<number | null>(null)

  const dbConnectionString = useMemo(
    () =>
      buildDbConnectionString({
        type: dbType,
        sslmode: dbSslMode,
        host: dbHost,
        port: dbPort,
        database: dbDatabase,
        username: dbUsername,
        password: dbPassword,
      }),
    [dbDatabase, dbHost, dbPassword, dbPort, dbSslMode, dbType, dbUsername],
  )

  const dbConnectionStringPreview = useMemo(() => {
    return getDbConnectionStringPreview(dbConnectionString, dbShowPassword)
  }, [dbConnectionString, dbShowPassword])

  const [error, setError] = useState<string | null>(null)

  const hasAnyHeader = useMemo(() => headersRows.some(r => r.key.trim() || r.value), [headersRows])
  const hasAnyVariable = useMemo(() => {
    if (baseUrlRow.key.trim() || baseUrlRow.value) return true
    return variablesRows.some(r => r.key.trim() || r.value)
  }, [baseUrlRow.key, baseUrlRow.value, variablesRows])

  function openDialog() {
    setError(null)
    setDbTestError(null)
    setDbTestLog(null)
    setDbTestOkMs(null)
    if (dbTestOkResetTimerRef.current) {
      window.clearTimeout(dbTestOkResetTimerRef.current)
      dbTestOkResetTimerRef.current = null
    }
    setDbTestInFlight(false)
    setBaseUrlRow({
      key: props.env.baseUrlKey,
      value: props.env.variables[props.env.baseUrlKey] ?? '',
    })
    setVariablesRows(
      ensureTrailingEmptyRow(
        Object.entries(props.env.variables)
          .filter(([k]) => k !== props.env.baseUrlKey && k !== 'scheme' && !shouldHideVariableKeyFromVariablesList(k))
          .map(([k, v]) => ({ key: k, value: v })),
      ),
    )
    setHeadersRows(
      ensureTrailingEmptyRow(Object.entries(props.env.headers).map(([k, v]) => ({ key: k, value: v }))),
    )
    const nextDb = getDbFormStateFromEnv(props.env)
    setDbType(nextDb.type)
    setDbSslMode(nextDb.sslmode)
    setDbHost(nextDb.host)
    setDbPort(nextDb.port)
    setDbDatabase(nextDb.database)
    setDbUsername(nextDb.username)
    setDbPassword(nextDb.password)
    setDbShowPassword(false)
    setDbAccordionOpen(hasDbConfigInEnv(props.env))
    dialogRef.current?.showModal()
  }

  function close() {
    dialogRef.current?.close()
  }

  useEffect(() => {
    const el = dialogRef.current
    if (!el) return
    if (props.open) {
      if (!el.open) openDialog()
    } else {
      if (el.open) el.close()
    }
  }, [props.open, props.env])

  useEffect(() => {
    if (!dbTypeMenuOpen) return

    function onPointerDown(e: PointerEvent) {
      const wrap = dbTypeMenuWrapRef.current
      const t = e.target as Node | null
      if (wrap && t && wrap.contains(t)) return
      setDbTypeMenuOpen(false)
    }

    function onKeyDown(e: KeyboardEvent) {
      if (e.key === 'Escape') setDbTypeMenuOpen(false)
    }

    window.addEventListener('pointerdown', onPointerDown)
    window.addEventListener('keydown', onKeyDown)
    return () => {
      window.removeEventListener('pointerdown', onPointerDown)
      window.removeEventListener('keydown', onKeyDown)
    }
  }, [dbTypeMenuOpen])

  useEffect(() => {
    if (!dbSslModeMenuOpen) return

    function onPointerDown(e: PointerEvent) {
      const wrap = dbSslModeMenuWrapRef.current
      const t = e.target as Node | null
      if (wrap && t && wrap.contains(t)) return
      setDbSslModeMenuOpen(false)
    }

    function onKeyDown(e: KeyboardEvent) {
      if (e.key === 'Escape') setDbSslModeMenuOpen(false)
    }

    window.addEventListener('pointerdown', onPointerDown)
    window.addEventListener('keydown', onKeyDown)
    return () => {
      window.removeEventListener('pointerdown', onPointerDown)
      window.removeEventListener('keydown', onKeyDown)
    }
  }, [dbSslModeMenuOpen])

  function setDbTypeAndMaybeDefaultPort(nextType: DbType) {
    setDbType(nextType)
    setDbSslModeMenuOpen(false)
    setDbPort(prev => {
      const raw = prev.trim()
      if (!raw) return nextType === 'mysql' ? '3306' : '5432'
      if (nextType === 'mysql' && raw === '5432') return '3306'
      if (nextType === 'postgres' && raw === '3306') return '5432'
      return prev
    })
  }

  function save() {
    setError(null)
    try {
      const normalizedBaseUrlKey = normalizeVarName(baseUrlRow.key)
      if (!normalizedBaseUrlKey) {
        setError('Base URL variable key is required.')
        return
      }

      const baseUrlValue = baseUrlRow.value.trim()
      const scheme =
        baseUrlValue.toLowerCase().startsWith('https://')
          ? 'https'
          : baseUrlValue.toLowerCase().startsWith('http://')
            ? 'http'
            : String(props.env.variables.scheme || 'http').toLowerCase() === 'https'
              ? 'https'
              : 'http'

      let variables: Record<string, string> = {
        scheme,
        [normalizedBaseUrlKey]: baseUrlValue,
      }
      for (const row of variablesRows) {
        const key = normalizeVarName(row.key)
        if (!key) continue
        if (key === normalizedBaseUrlKey) continue
        if (key === 'scheme') continue
        if (shouldHideVariableKeyFromVariablesList(key)) continue
        variables[key] = row.value ?? ''
      }

      variables = mergeDbIntoVariables(variables, {
        type: dbType,
        sslmode: dbSslMode,
        host: dbHost,
        port: dbPort,
        database: dbDatabase,
        username: dbUsername,
        password: dbPassword,
      })

      const headers: Record<string, string> = {}
      for (const row of headersRows) {
        const key = row.key.trim()
        if (!key) continue
        headers[key] = row.value ?? ''
      }

      props.onSave({
        baseUrlKey: normalizedBaseUrlKey,
        variables,
        headers,
      })
      close()
    } catch (e: any) {
      setError(e?.message || 'Invalid environment settings.')
    }
  }

  async function testDbConnection() {
    setError(null)
    setDbTestError(null)
    setDbTestLog(null)
    setDbTestOkMs(null)
    if (dbTestOkResetTimerRef.current) {
      window.clearTimeout(dbTestOkResetTimerRef.current)
      dbTestOkResetTimerRef.current = null
    }

    const connectionString = dbConnectionString.trim()
    if (!connectionString) {
      setDbTestError('Connection failed')
      setDbTestLog('Fill host/port/database/user/password to build connection string.')
      return
    }

    setDbTestInFlight(true)
    try {
      const { ok, message, durationMs } = await runDbConnectionTest({ type: dbType.trim() || 'postgres', connectionString })
      if (ok) {
        setDbTestOkMs(durationMs)
        dbTestOkResetTimerRef.current = window.setTimeout(() => {
          setDbTestOkMs(null)
          dbTestOkResetTimerRef.current = null
        }, 2500)
      } else {
        setDbTestError('Connection failed')
        setDbTestLog(message)
      }
    } catch (e) {
      const message = e instanceof Error ? e.message : 'Network error'
      setDbTestError('Connection failed')
      setDbTestLog(message)
    } finally {
      setDbTestInFlight(false)
    }
  }

  function clearDbFormKeepPort() {
    setDbHost('')
    setDbDatabase('')
    setDbUsername('')
    setDbPassword('')
    setDbSslMode('prefer')
    setDbShowPassword(false)

    setDbTestError(null)
    setDbTestLog(null)
    setDbTestOkMs(null)
    if (dbTestOkResetTimerRef.current) {
      window.clearTimeout(dbTestOkResetTimerRef.current)
      dbTestOkResetTimerRef.current = null
    }
  }

  function clearBaseUrlValue() {
    setBaseUrlRow(prev => ({ ...prev, value: '' }))
  }

  function updateVariableRow(i: number, next: VariableRow) {
    setVariablesRows(prev => prev.map((r, idx) => (idx === i ? next : r)))
  }

  function deleteVariableRow(i: number) {
    setVariablesRows(prev => ensureTrailingEmptyRow(prev.filter((_r, idx) => idx !== i)))
  }

  function updateHeaderRow(i: number, next: HeaderRow) {
    setHeadersRows(prev => prev.map((r, idx) => (idx === i ? next : r)))
  }

  function deleteHeaderRow(i: number) {
    setHeadersRows(prev => ensureTrailingEmptyRow(prev.filter((_r, idx) => idx !== i)))
  }

  function addNextVariableRowIfPossible(i: number) {
    setVariablesRows(prev => {
      const row = prev[i]
      const isLast = i === prev.length - 1
      if (!row || !isLast) return prev
      if (!row.key.trim() && !row.value) return prev
      return [...prev, { key: '', value: '' }]
    })
  }

  function addNextHeaderRowIfPossible(i: number) {
    setHeadersRows(prev => {
      const row = prev[i]
      const isLast = i === prev.length - 1
      if (!row || !isLast) return prev
      if (!row.key.trim() && !row.value) return prev
      return [...prev, { key: '', value: '' }]
    })
  }

  return (
    <dialog ref={dialogRef} className="modal" onClose={() => props.onClose()}>
      <div className="modalHeader">
        <b>Enviroment: {props.collectionName}</b>
        <button className="iconBtn" onClick={close} aria-label="Close" title="Close">
          <CloseIcon size={18} />
        </button>
      </div>

      <div style={{ display: 'grid', gap: 10 }}>
        <div>
          <div style={{ display: 'flex', alignItems: 'center', justifyContent: 'space-between', gap: 10, marginBottom: 6 }}>
            <div className="small">Variables</div>
          </div>

          {!hasAnyVariable && (
            <div className="small" style={{ marginBottom: 8 }}>
              You can use variables like <span className="mono">{'{{var}}'}</span> in the URL, headers, and body.
            </div>
          )}

          <div style={{ display: 'grid', gap: 8 }}>
            <div style={{ display: 'grid', gridTemplateColumns: '220px 1fr auto', gap: 10 }}>
              <input
                className="mono"
                value={baseUrlRow.key}
                onChange={e => setBaseUrlRow(prev => ({ ...prev, key: e.target.value }))}
                placeholder="key"
              />
              <input
                className="mono"
                value={baseUrlRow.value}
                onChange={e => setBaseUrlRow(prev => ({ ...prev, value: e.target.value }))}
                placeholder="value"
              />
              <button
                className="headerDeleteBtn"
                onClick={clearBaseUrlValue}
                aria-label="Clear variable value"
                title="Clear variable value"
              >
                <CloseIcon size={18} />
              </button>
            </div>
            {variablesRows.map((row, i) => {
              const isLast = i === variablesRows.length - 1
              const canAdd = !!(row.key.trim() || row.value)
              return (
                <div key={i} style={{ display: 'grid', gridTemplateColumns: '220px 1fr auto', gap: 10 }}>
                  <input
                    className="mono"
                    value={row.key}
                    onChange={e => updateVariableRow(i, { ...row, key: e.target.value })}
                    placeholder="Key"
                  />
                  <input
                    className="mono"
                    value={row.value}
                    onChange={e => updateVariableRow(i, { ...row, value: e.target.value })}
                    placeholder="Value"
                  />
                  {isLast ? (
                    <button
                      className="headerDeleteBtn addRowBtn"
                      onClick={() => addNextVariableRowIfPossible(i)}
                      disabled={!canAdd}
                      aria-label="Add variable"
                      title={canAdd ? 'Add' : 'Fill key/value to add'}
                    >
                      <span className="addRowGlyph">+</span>
                    </button>
                  ) : (
                    <button
                      className="headerDeleteBtn"
                      onClick={() => deleteVariableRow(i)}
                      aria-label="Delete variable"
                      title="Delete"
                    >
                      <CloseIcon size={18} />
                    </button>
                  )}
                </div>
              )
            })}
          </div>
        </div>

        <div>
          <div style={{ display: 'flex', alignItems: 'center', justifyContent: 'space-between', gap: 10, marginBottom: 6 }}>
            <div className="small">Headers</div>
          </div>

          {!hasAnyHeader ? null : null}

          <div style={{ display: 'grid', gap: 8 }}>
            {headersRows.map((row, i) => {
              const isLast = i === headersRows.length - 1
              const canAdd = !!(row.key.trim() || row.value)
              return (
                <div key={i} style={{ display: 'grid', gridTemplateColumns: '220px 1fr auto', gap: 10 }}>
                  <input
                    className="mono"
                    value={row.key}
                    onChange={e => updateHeaderRow(i, { ...row, key: e.target.value })}
                    placeholder="Key"
                  />
                  <input
                    className="mono"
                    value={row.value}
                    onChange={e => updateHeaderRow(i, { ...row, value: e.target.value })}
                    placeholder="Value"
                  />
                  {isLast ? (
                    <button
                      className="headerDeleteBtn addRowBtn"
                      onClick={() => addNextHeaderRowIfPossible(i)}
                      disabled={!canAdd}
                      aria-label="Add header"
                      title={canAdd ? 'Add' : 'Fill key/value to add'}
                    >
                      <span className="addRowGlyph">+</span>
                    </button>
                  ) : (
                    <button
                      className="headerDeleteBtn"
                      onClick={() => deleteHeaderRow(i)}
                      aria-label="Delete header"
                      title="Delete"
                    >
                      <CloseIcon size={18} />
                    </button>
                  )}
                </div>
              )
            })}
          </div>
        </div>

        <details
          className="accordion"
          style={{ marginTop: 10 }}
          open={dbAccordionOpen}
          onToggle={e => setDbAccordionOpen((e.currentTarget as HTMLDetailsElement).open)}
        >
          <summary>
            <span style={{ flex: 1 }}>Database</span>
            <button
              type="button"
              className="iconBtn"
              style={{ width: 28, height: 28, marginLeft: 'auto' }}
              onClick={e => {
                e.preventDefault()
                e.stopPropagation()
                clearDbFormKeepPort()
              }}
              aria-label="Clear database form"
              title="Clear"
            >
              <CloseIcon size={18} />
            </button>
          </summary>
          <div className="section">
            <div className="formRow">
              <div className="formLabel">Type</div>
              <div ref={dbTypeMenuOpen ? dbTypeMenuWrapRef : null} className="selectMenuWrap">
                <button
                  type="button"
                  className="selectMenuBtn"
                  onPointerDown={e => e.stopPropagation()}
                  onClick={e => {
                    e.preventDefault()
                    e.stopPropagation()
                    setDbTypeMenuOpen(v => !v)
                  }}
                  aria-haspopup="menu"
                  aria-expanded={dbTypeMenuOpen}
                  aria-label="Database type"
                  title="Database type"
                >
                  {dbType === 'mysql' ? 'MySQL' : 'PostgreSQL'}
                </button>

                {dbTypeMenuOpen ? (
                  <div
                    className="selectMenuPanel"
                    role="menu"
                    onPointerDown={e => {
                      e.preventDefault()
                      e.stopPropagation()
                    }}
                    onClick={e => {
                      e.preventDefault()
                      e.stopPropagation()
                    }}
                  >
                    <button
                      type="button"
                      className={`selectMenuItem ${dbType === 'postgres' ? 'selectMenuItemActive' : ''}`}
                      role="menuitem"
                      onClick={() => {
                        setDbTypeMenuOpen(false)
                        setDbTypeAndMaybeDefaultPort('postgres')
                      }}
                    >
                      PostgreSQL
                    </button>
                    <button
                      type="button"
                      className={`selectMenuItem ${dbType === 'mysql' ? 'selectMenuItemActive' : ''}`}
                      role="menuitem"
                      onClick={() => {
                        setDbTypeMenuOpen(false)
                        setDbTypeAndMaybeDefaultPort('mysql')
                      }}
                    >
                      MySQL
                    </button>
                  </div>
                ) : null}
              </div>
            </div>

            {dbType === 'postgres' ? (
              <div className="formRow">
                <div className="formLabel">SSL mode</div>
                <div ref={dbSslModeMenuOpen ? dbSslModeMenuWrapRef : null} className="selectMenuWrap">
                  <button
                    type="button"
                    className="selectMenuBtn"
                    onPointerDown={e => e.stopPropagation()}
                    onClick={e => {
                      e.preventDefault()
                      e.stopPropagation()
                      setDbSslModeMenuOpen(v => !v)
                    }}
                    aria-haspopup="menu"
                    aria-expanded={dbSslModeMenuOpen}
                    aria-label="PostgreSQL SSL mode"
                    title="PostgreSQL SSL mode"
                  >
                    {dbSslMode}
                  </button>

                  {dbSslModeMenuOpen ? (
                    <div
                      className="selectMenuPanel"
                      role="menu"
                      onPointerDown={e => {
                        e.preventDefault()
                        e.stopPropagation()
                      }}
                      onClick={e => {
                        e.preventDefault()
                        e.stopPropagation()
                      }}
                    >
                      {([
                        { value: 'prefer', label: 'prefer (default)' },
                        { value: 'require', label: 'require (encrypt, no verify)' },
                        { value: 'verify-ca', label: 'verify-ca' },
                        { value: 'verify-full', label: 'verify-full' },
                        { value: 'disable', label: 'disable' },
                        { value: 'allow', label: 'allow' },
                      ] as Array<{ value: PgSslMode; label: string }>).map(o => (
                        <button
                          key={o.value}
                          type="button"
                          className={`selectMenuItem ${dbSslMode === o.value ? 'selectMenuItemActive' : ''}`}
                          role="menuitem"
                          onClick={() => {
                            setDbSslModeMenuOpen(false)
                            setDbSslMode(o.value)
                          }}
                        >
                          {o.label}
                        </button>
                      ))}
                    </div>
                  ) : null}
                </div>
              </div>
            ) : null}

            <div className="formRow">
              <div className="formLabel">Host</div>
              <input
                className="mono"
                value={dbHost}
                onChange={e => setDbHost(e.target.value)}
                placeholder="localhost"
              />
            </div>

            <div className="formRow">
              <div className="formLabel">Port</div>
              <input
                className="mono"
                inputMode="numeric"
                value={dbPort}
                onChange={e => setDbPort(e.target.value.replaceAll(/\s+/g, ''))}
                placeholder="5432"
              />
            </div>

            <div className="formRow">
              <div className="formLabel">Database</div>
              <input
                className="mono"
                value={dbDatabase}
                onChange={e => setDbDatabase(e.target.value)}
                placeholder="mydb"
              />
            </div>

            <div className="formRow">
              <div className="formLabel">Username</div>
              <input
                className="mono"
                value={dbUsername}
                onChange={e => setDbUsername(e.target.value)}
                placeholder="postgres"
              />
            </div>

            <div className="formRow">
              <div className="formLabel">Password</div>
              <div style={{ display: 'grid', gridTemplateColumns: '1fr auto', gap: 10, alignItems: 'center' }}>
                <input
                  className="mono"
                  type="text"
                  name="ruf_db_secret"
                  value={dbPassword}
                  onChange={e => setDbPassword(e.target.value)}
                  autoComplete="off"
                  autoCorrect="off"
                  autoCapitalize="none"
                  spellCheck={false}
                  style={dbShowPassword ? undefined : ({ WebkitTextSecurity: 'disc' } as any)}
                  placeholder="••••••••"
                />
                <button
                  type="button"
                  className="headerDeleteBtn"
                  style={{ width: 64 }}
                  onClick={() => setDbShowPassword(v => !v)}
                  aria-label={dbShowPassword ? 'Hide password' : 'Show password'}
                  title={dbShowPassword ? 'Hide' : 'Show'}
                >
                  {dbShowPassword ? 'Hide' : 'Show'}
                </button>
              </div>
            </div>

            <div className="formRow">
              <div className="formLabel">URL</div>
              <div style={{ display: 'grid', gridTemplateColumns: '1fr auto', gap: 10, alignItems: 'center' }}>
                <div
                  className="mono"
                  style={{
                    fontSize: 12,
                    lineHeight: 1.25,
                    opacity: dbConnectionStringPreview ? 1 : 0.7,
                    overflowWrap: 'anywhere',
                    wordBreak: 'break-word',
                    whiteSpace: 'normal',
                  }}
                >
                  {dbConnectionStringPreview || '—'}
                </div>
                <button
                  type="button"
                  className="headerDeleteBtn"
                  style={
                    dbTestOkMs !== null
                      ? { width: 64, background: 'rgba(80, 220, 140, .18)', borderColor: 'rgba(80, 220, 140, .45)', color: 'rgb(120, 255, 185)' }
                      : { width: 64 }
                  }
                  onClick={testDbConnection}
                  disabled={dbTestInFlight || !dbConnectionString}
                >
                  {dbTestInFlight ? 'Testing...' : dbTestOkMs !== null ? `${dbTestOkMs}ms` : 'Test'}
                </button>
              </div>
            </div>

            {dbTestError && (
              <div className="section" style={{ gap: 6 }}>
                <div className="small" style={{ color: '#ff9a9a' }}>{dbTestError}</div>
                {dbTestLog && (
                  <div
                    className="mono"
                    style={{
                      fontSize: 12,
                      lineHeight: 1.35,
                      padding: 10,
                      borderRadius: 10,
                      border: '1px solid rgba(255,255,255,.12)',
                      background: 'rgba(255,255,255,.04)',
                      whiteSpace: 'pre-wrap',
                      overflowWrap: 'anywhere',
                    }}
                  >
                    {dbTestLog}
                  </div>
                )}
              </div>
            )}
          </div>
        </details>
      </div>

      {error && <div className="small" style={{ color: '#ff9a9a', marginTop: 8 }}>{error}</div>}

      <div className="modalActions">
        <button onClick={save}>Save</button>
      </div>
    </dialog>
  )
}

import type { Collection, Folder, RequestItem } from '../../collectionTree'
import type { Environment } from '../../../shared/types/environment'
import { uid } from '../../../shared/utils/id'
import { computeEffectiveBaseUrl, isAbsoluteUrl } from '../../../shared/utils/url'
import { isDbEnvKey } from '../../environment/utils/dbConnection'

function applySchemeIfHostLike(url: string, scheme: 'http' | 'https') {
  const raw = url.trim().replace(/\/+$/, '')
  if (!raw) return ''
  if (isAbsoluteUrl(raw) || raw.startsWith('/') || raw.startsWith('//')) return raw

  const looksLikeHost =
    /^localhost(?::\d+)?(?:\/.*)?$/i.test(raw) ||
    /^\d{1,3}(?:\.\d{1,3}){3}(?::\d+)?(?:\/.*)?$/.test(raw) ||
    /^[a-z0-9.-]+\.[a-z]{2,}(?::\d+)?(?:\/.*)?$/i.test(raw)

  if (!looksLikeHost) return raw
  return `${scheme}://${raw}`.replace(/\/+$/, '')
}

function getHeaderCaseInsensitive(headers: Record<string, string>, name: string): string | undefined {
  const needle = name.toLowerCase()
  for (const [k, v] of Object.entries(headers)) {
    if (k.toLowerCase() === needle) return v
  }
  return undefined
}

function setHeaderCaseInsensitive(headers: Record<string, string>, name: string, value: string) {
  const needle = name.toLowerCase()
  for (const k of Object.keys(headers)) {
    if (k.toLowerCase() === needle) {
      headers[k] = value
      return
    }
  }
  headers[name] = value
}

function toPostmanPathParamSyntax(path: string) {
  return path.replaceAll(/\{([^}]+)\}/g, (_m: string, name: string) => `:${name}`)
}

function toPostmanUrlObject(req: RequestItem) {
  const raw = toPostmanPathParamSyntax((req.urlTemplate || '').trim() || '{{baseUrl}}/')
  const pathSegments = toPostmanPathParamSyntax((req.path || '').trim())
    .replace(/^\//, '')
    .split('/')
    .filter(Boolean)

  const query = (req.params ?? [])
    .filter(p => p?.in === 'query')
    .map(p => {
      const example = p?.example
      const value = typeof example === 'string' ? example : example == null ? '' : JSON.stringify(example)
      const disabled = value === ''
      return { key: p.name, value, disabled }
    })

  const variable = (req.params ?? [])
    .filter(p => p?.in === 'path')
    .map(p => {
      const example = p?.example
      const value = typeof example === 'string' ? example : example == null ? '' : JSON.stringify(example)
      return { key: p.name, value }
    })

  // Postman accepts partial Url objects; "raw" is the most important part for import.
  if (raw.startsWith('{{baseUrl}}')) {
    return {
      raw,
      host: ['{{baseUrl}}'],
      path: pathSegments,
      query,
      variable,
    }
  }

  if (isAbsoluteUrl(raw) && !raw.includes('{{')) {
    try {
      const u = new URL(raw)
      const host = u.hostname ? u.hostname.split('.').filter(Boolean) : []
      const port = u.port ? u.port : undefined
      const protocol = u.protocol ? u.protocol.replace(/:$/, '') : undefined
      const urlPath = (u.pathname || '').replace(/^\//, '').split('/').filter(Boolean)
      return {
        raw,
        protocol,
        host,
        port,
        path: urlPath,
        query,
        variable,
      }
    } catch {
      // fall through
    }
  }

  return { raw, path: pathSegments, query, variable }
}

function toPostmanRequestItem(req: RequestItem, _environment?: Environment) {
  const headers: Record<string, string> = { ...(req.headers ?? {}) }
  const contentType = (req.body?.contentType || '').trim()
  if (req.body && contentType && !getHeaderCaseInsensitive(headers, 'Content-Type')) {
    setHeaderCaseInsensitive(headers, 'Content-Type', contentType)
  }

  const header = Object.entries(headers).map(([key, value]) => ({ key, value }))

  const body = (() => {
    if (!req.body) return undefined
    const ct = (req.body.contentType || '').trim().toLowerCase()
    const isJson = ct.includes('json')
    const example = req.body.example
    const raw =
      typeof example === 'string'
        ? example
        : example == null
          ? ''
          : JSON.stringify(example, null, 2)
    return isJson
      ? { mode: 'raw', raw, options: { raw: { language: 'json' } } }
      : { mode: 'raw', raw }
  })()

  return {
    name: req.name,
    request: {
      method: req.method,
      header,
      url: toPostmanUrlObject(req),
      ...(body ? { body } : {}),
    },
  }
}

function toPostmanFolder(folder: Folder, environment?: Environment) {
  const items: any[] = []
  for (const f of folder.folders ?? []) items.push(toPostmanFolder(f, environment))
  for (const r of folder.requests ?? []) items.push(toPostmanRequestItem(r, environment))
  return { name: folder.name, item: items }
}

export function buildPostmanCollectionFromRufCollection(args: {
  collection: Collection
  environment?: Environment
}) {
  const envVarsRaw = args.environment?.variables ?? {}
  const envVars = Object.fromEntries(Object.entries(envVarsRaw).filter(([k]) => !isDbEnvKey(k)))
  const envKey = args.environment?.baseUrlKey || 'baseUrl'
  const envBaseUrl = envVars[envKey] ?? ''
  const scheme = String(envVars.scheme || '').trim().toLowerCase() === 'https' ? 'https' : 'http'
  const effectiveBaseUrl = applySchemeIfHostLike(computeEffectiveBaseUrl(envBaseUrl, args.collection.baseUrl), scheme)

  const variables: Record<string, string> = {
    ...Object.fromEntries(Object.entries(args.collection.variables ?? {}).filter(([k]) => !isDbEnvKey(k))),
    ...envVars,
    scheme,
    baseUrl: effectiveBaseUrl,
  }

  const variable = Object.entries(variables)
    .filter(([k]) => k.trim())
    .map(([key, value]) => ({ key, value: value ?? '' }))

  const items: any[] = []
  for (const f of args.collection.folders ?? []) items.push(toPostmanFolder(f, args.environment))
  for (const r of args.collection.requests ?? []) items.push(toPostmanRequestItem(r, args.environment))

  return {
    info: {
      _postman_id: uid('postman'),
      name: args.collection.name,
      schema: 'https://schema.getpostman.com/json/collection/v2.1.0/collection.json',
    },
    item: items,
    variable,
    // Extra metadata for round-tripping back into RUF. Postman should ignore unknown keys.
    rufEnvironment: args.environment
      ? {
          baseUrlKey: args.environment.baseUrlKey,
          variables: envVars,
        }
      : undefined,
  }
}

import { loadOpenApiFromText, parseJsonOrYaml } from './openapi/openapiLoader'
import { buildCollectionFromV3, type Collection } from '../collectionTree'
import { buildCollectionFromPostman, isPostmanCollection } from './postman/postmanCollection'
import { buildCollectionFromInsomnia, isInsomniaExport } from './insomnia/insomniaCollection'
import { buildCollectionFromWsdlText, isWsdlText } from './wsdl/wsdlImporter'
import type { Environment } from '../../shared/types/environment'
import { isDbEnvKey } from '../environment/utils/dbConnection'

function inferCollectionName(spec: any) {
  const title = spec?.info?.title
  if (typeof title === 'string' && title.trim()) return title.trim()
  return 'Imported API'
}

function parseRufEnvironment(raw: any): Environment | null {
  if (!raw || typeof raw !== 'object') return null
  const baseUrlKey = typeof (raw as any).baseUrlKey === 'string' && (raw as any).baseUrlKey.trim()
    ? String((raw as any).baseUrlKey).trim()
    : 'baseUrl'

  const varsObj = (raw as any).variables && typeof (raw as any).variables === 'object' ? (raw as any).variables : {}
  const variables: Record<string, string> = {}
  for (const [k, v] of Object.entries(varsObj)) {
    if (typeof k !== 'string' || !k.trim()) continue
    if (isDbEnvKey(k)) continue
    variables[k] = typeof v === 'string' ? v : v == null ? '' : String(v)
  }
  return { baseUrlKey, variables, headers: {} }
}

export async function buildImportedCollectionFromText(args: {
  text: string
  name?: string
  sourceOrigin?: string
}): Promise<Collection> {
  if (isWsdlText(args.text)) {
    return buildCollectionFromWsdlText(args.text, args.name)
  }

  const parsed = parseJsonOrYaml(args.text)
  if (isPostmanCollection(parsed)) {
    const col = buildCollectionFromPostman(parsed, args.name)
    const env = parseRufEnvironment((parsed as any)?.rufEnvironment)
    if (env) {
      Object.defineProperty(col, '__rufEnvironment', {
        value: env,
        enumerable: false,
        configurable: true,
      })
    }
    return col
  }
  if (isInsomniaExport(parsed)) {
    return buildCollectionFromInsomnia(parsed, args.name)
  }

  const specV3 = await loadOpenApiFromText(args.text)
  const name = (args.name || inferCollectionName(specV3)).trim() || 'Imported API'
  return buildCollectionFromV3(specV3, name, args.sourceOrigin)
}

import { useEffect, useRef, useState } from 'react'
import type { Collection } from '../../collectionTree'
import { buildImportedCollectionFromText } from '../buildImportedCollection'
import { fetchWithProxyFallback } from '../../../shared/utils/proxyFetch'
import { loadAppSettings } from '../../../shared/utils/appSettings'

export function ImportFab(props: {
  onImported: (c: Collection) => void
  variant?: 'fab' | 'button'
  label?: string
  showTrigger?: boolean
  openRef?: React.MutableRefObject<{
    openMenu: () => void
    openNameStep: (col: Collection) => void
  } | null>
}) {
  const menuRef = useRef<HTMLDialogElement | null>(null)
  const fileInputRef = useRef<HTMLInputElement | null>(null)
  const variant = props.variant ?? 'fab'
  const label = props.label ?? 'Import'
  const showTrigger = props.showTrigger ?? true

  const [view, setView] = useState<'menu' | 'json' | 'url' | 'name'>('menu')
  const [menuError, setMenuError] = useState<string | null>(null)

  const [jsonText, setJsonText] = useState('')
  const [jsonError, setJsonError] = useState<string | null>(null)

  const [specUrl, setSpecUrl] = useState('')
  const [urlError, setUrlError] = useState<string | null>(null)
  const [loadingUrl, setLoadingUrl] = useState(false)

  const [pendingCollection, setPendingCollection] = useState<Collection | null>(null)
  const [pendingName, setPendingName] = useState('')
  const [nameError, setNameError] = useState<string | null>(null)

  async function importFromText(text: string, origin?: string) {
    return buildImportedCollectionFromText({ text, sourceOrigin: origin })
  }

  function openNameStep(col: Collection) {
    setPendingCollection(col)
    setPendingName(col.name ?? '')
    setNameError(null)
    setView('name')
  }

  function openNameStepFromOutside(col: Collection) {
    openNameStep(col)
    menuRef.current?.showModal()
  }

  function confirmAddCollection() {
    const col = pendingCollection
    if (!col) return

    const name = pendingName.trim()
    if (!name) {
      setNameError('Enter a collection name.')
      return
    }

    props.onImported({ ...col, name })
    closeMenu()
  }

  function openMenu() {
    setView('menu')
    setMenuError(null)
    menuRef.current?.showModal()
  }

  useEffect(() => {
    if (!props.openRef) return
    props.openRef.current = { openMenu, openNameStep: openNameStepFromOutside }
    return () => {
      props.openRef!.current = null
    }
  }, [props.openRef])

  function closeMenu() {
    menuRef.current?.close()
    setView('menu')
    setMenuError(null)
    setPendingCollection(null)
    setPendingName('')
    setNameError(null)
  }

  function chooseFile() {
    setMenuError(null)
    fileInputRef.current?.click()
  }

  async function onFileSelected(e: React.ChangeEvent<HTMLInputElement>) {
    const file = e.target.files?.[0]
    if (!file) return
    try {
      const text = await file.text()
      const col = await importFromText(text)
      openNameStep({ ...col, sourceType: 'file', sourceFileName: file.name })
    } catch (err: any) {
      setMenuError(err?.message || 'Failed to import file.')
    } finally {
      e.target.value = ''
    }
  }

  function openJson() {
    setMenuError(null)
    setJsonError(null)
    setJsonText('')
    setView('json')
  }

  async function importJson() {
    setJsonError(null)
    try {
      if (!jsonText.trim()) {
        setJsonError('Paste the spec first.')
        return
      }
      const col = await importFromText(jsonText)
      openNameStep(col)
    } catch (e: any) {
      setJsonError(e?.message || 'Failed to import.')
    }
  }

  function openUrl() {
    setMenuError(null)
    setUrlError(null)
    setSpecUrl('')
    setView('url')
  }

  async function importUrl() {
    setUrlError(null)
    setLoadingUrl(true)
    try {
      const raw = specUrl.trim()
      if (!raw) {
        setUrlError('Enter a URL.')
        return
      }
      const u = new URL(raw)
      const { validateCertificates, caCertificates } = loadAppSettings()
      const res = await fetchWithProxyFallback(u.toString(), undefined, { insecureTls: !validateCertificates, caCertsPem: (caCertificates || []).map(c => c.pem) })
      if (!res.ok) throw new Error(`HTTP ${res.status} ${res.statusText}`)
      const text = await res.text()
      if (!text.trim()) {
        setUrlError('Empty response.')
        return
      }
      const col = await importFromText(text, u.origin)
      openNameStep({ ...col, sourceUrl: u.toString(), sourceType: 'url' })
    } catch (e: any) {
      setUrlError(e?.message || 'Failed to load URL.')
    } finally {
      setLoadingUrl(false)
    }
  }

  return (
    <>
      <input
        ref={fileInputRef}
        type="file"
        accept=".ruf_collection,.rufcollection,.json,.yaml,.yml,.wsdl,.xml"
        style={{ display: 'none' }}
        onChange={onFileSelected}
      />

      {showTrigger ? (
        variant === 'button' ? (
          <button onClick={openMenu}>{label}</button>
        ) : (
          <button className="fab" onClick={openMenu} aria-label="Import">
            <span className="fabIcon">+</span>
          </button>
        )
      ) : null}

      <dialog ref={menuRef} className={variant === 'button' ? 'modal modalSmall' : 'modal fabMenu'}>
        <div className="modalHeader">
          <b>{view === 'name' ? 'Add collection' : 'Import'}</b>
          <button className="iconBtn" onClick={closeMenu} aria-label="Close">✕</button>
        </div>

        {view === 'menu' && (
          <>
            <div className="importMenuGrid">
              <button className="importMenuBtn" onClick={chooseFile}>File</button>
              <button className="importMenuBtn" onClick={openJson}>Text</button>
              <button className="importMenuBtn" onClick={openUrl}>URL</button>
            </div>
            <div className="importHint" style={{ marginTop: 10 }}>
              Supported: OpenAPI/Swagger (JSON/YAML), Postman (JSON), Insomnia (YAML/JSON), WSDL (WSDL/XML).
            </div>
            {menuError && (
              <div className="small" style={{ color: '#ff9a9a', marginTop: 8 }}>
                {menuError}
              </div>
            )}
          </>
        )}

        {view === 'json' && (
          <>
            <textarea
              className="mono modalTextarea"
              value={jsonText}
              onChange={e => setJsonText(e.target.value)}
              placeholder="Paste OpenAPI / Postman / Insomnia / WSDL..."
            />
            {jsonError && <div className="small" style={{ color: '#ff9a9a', marginTop: 8 }}>{jsonError}</div>}
            <div className="modalActions">
              <button onClick={() => setView('menu')}>Back</button>
              <button onClick={importJson}>Import</button>
            </div>
          </>
        )}

        {view === 'url' && (
          <>
            <div className="importHint" style={{ marginBottom: 8 }}>
              Enter a URL to OpenAPI / Postman / Insomnia / WSDL.
            </div>
            <input
              className="mono"
              style={{ width: '100%' }}
              value={specUrl}
              onChange={e => setSpecUrl(e.target.value)}
              placeholder="https://example.com/openapi.json"
            />
            {urlError && <div className="small" style={{ color: '#ff9a9a', marginTop: 8 }}>{urlError}</div>}
            <div className="modalActions">
              <button onClick={() => setView('menu')}>Back</button>
              <button onClick={importUrl} disabled={loadingUrl}>
                {loadingUrl ? 'Loading...' : 'Import'}
              </button>
            </div>
          </>
        )}

        {view === 'name' && (
          <form
            onSubmit={e => {
              e.preventDefault()
              confirmAddCollection()
            }}
          >
            <div style={{ display: 'grid', gridTemplateColumns: '1fr', gap: 10 }}>
              <div className="importHint">Collection name</div>
              <input
                style={{ width: '100%' }}
                value={pendingName}
                onChange={e => setPendingName(e.target.value)}
                onFocus={e => e.currentTarget.select()}
                autoFocus
                placeholder="My API"
              />
            </div>

            {nameError && <div className="small" style={{ color: '#ff9a9a', marginTop: 8 }}>{nameError}</div>}

            <div className="modalActions">
              <button type="submit">Add collection</button>
            </div>
          </form>
        )}
      </dialog>
    </>
  )
}

import { useRef, useState, type ChangeEvent } from 'react'
import type { Collection } from '../../collectionTree'
import { buildImportedCollectionFromText } from '../buildImportedCollection'
import { fetchWithProxyFallback } from '../../../shared/utils/proxyFetch'
import { loadAppSettings } from '../../../shared/utils/appSettings'

export function ImportSpec(props: { onImported: (c: Collection) => void }) {
  const [error, setError] = useState<string | null>(null)
  const [name, setName] = useState('Imported API')

  const pasteDialogRef = useRef<HTMLDialogElement | null>(null)
  const pasteTextareaRef = useRef<HTMLTextAreaElement | null>(null)
  const [pasteText, setPasteText] = useState('')
  const [pasteError, setPasteError] = useState<string | null>(null)
  const canReadClipboard = !!(globalThis.isSecureContext && navigator.clipboard?.readText)
  const [sourceUrl, setSourceUrl] = useState('')
  const [sourceOrigin, setSourceOrigin] = useState<string | undefined>(undefined)
  const [loadingUrl, setLoadingUrl] = useState(false)

  async function importFromText(text: string, origin?: string, importedFromUrl?: string) {
    const col = await buildImportedCollectionFromText({ text, name: name || undefined, sourceOrigin: origin })
    props.onImported(importedFromUrl ? { ...col, sourceUrl: importedFromUrl } : col)
  }

  async function onFile(e: ChangeEvent<HTMLInputElement>) {
    setError(null)
    const file = e.target.files?.[0]
    if (!file) return
    const text = await file.text()

    try {
      await importFromText(text)
    } catch (err: any) {
      setError(err?.message || 'Failed to import spec.')
    } finally {
      e.target.value = ''
    }
  }

  function openPasteDialog() {
    setPasteError(null)
    setPasteText('')
    setSourceUrl('')
    setSourceOrigin(undefined)
    pasteDialogRef.current?.showModal()
    setTimeout(() => pasteTextareaRef.current?.focus(), 0)
  }

  async function pasteFromClipboard() {
    setPasteError(null)
    try {
      if (!canReadClipboard) {
        setPasteError("Clipboard access isn't available in this context. Paste manually into the field (Ctrl+V).")
        return
      }
      const t = await navigator.clipboard.readText()
      setPasteText(t)
      if (!t.trim()) setPasteError('Clipboard is empty.')
    } catch (e: any) {
      setPasteError(e?.message || 'Failed to read from clipboard.')
    }
  }

  async function submitPasted() {
    setError(null)
    setPasteError(null)

    try {
      if (!pasteText.trim()) {
        setPasteError('Paste OpenAPI JSON/YAML first.')
        return
      }
      const rawUrl = sourceUrl.trim()
      let normalizedUrl: string | undefined
      if (rawUrl) {
        try {
          normalizedUrl = new URL(rawUrl).toString()
        } catch {
          // ignore invalid url
        }
      }
      await importFromText(pasteText, sourceOrigin, normalizedUrl)
      pasteDialogRef.current?.close()
    } catch (e: any) {
      setPasteError(e?.message || 'Failed to import spec.')
    }
  }

  async function loadFromUrl() {
    setPasteError(null)
    setLoadingUrl(true)
    try {
      const url = sourceUrl.trim()
      if (!url) {
        setPasteError('Enter a URL first.')
        return
      }

      const u = new URL(url)
      const { validateCertificates, caCertificates } = loadAppSettings()
      const res = await fetchWithProxyFallback(u.toString(), undefined, { insecureTls: !validateCertificates, caCertsPem: (caCertificates || []).map(c => c.pem) })
      if (!res.ok) {
        throw new Error(`HTTP ${res.status} ${res.statusText}`)
      }
      const text = await res.text()
      setPasteText(text)
      setSourceOrigin(u.origin)
      if (!text.trim()) setPasteError('Response is empty.')
      setTimeout(() => pasteTextareaRef.current?.focus(), 0)
    } catch (e: any) {
      setPasteError(e?.message || 'Failed to load from URL.')
      setSourceOrigin(undefined)
    } finally {
      setLoadingUrl(false)
    }
  }

  return (
    <div style={{ display: 'flex', gap: 8, alignItems: 'center' }}>
      <input
        value={name}
        onChange={e => setName(e.target.value)}
        placeholder="Collection name"
      />
      <input type="file" accept=".json,.yaml,.yml,.wsdl,.xml" onChange={onFile} />
      <button onClick={openPasteDialog}>Paste</button>
      {error && (
        <span className="small" style={{ color: '#ff9a9a' }}>
          {error}
        </span>
      )}

      <dialog ref={pasteDialogRef} className="modal">
        <div className="modalHeader">
          <b>Import from text</b>
          <button onClick={() => pasteDialogRef.current?.close()}>Close</button>
        </div>

        <div className="small" style={{ marginBottom: 8 }}>
          Paste OpenAPI/Swagger JSON or YAML. Local refs like{' '}
          <span className="mono">#/components/...</span> are supported.
        </div>

        <div style={{display:'grid', gridTemplateColumns:'1fr auto', gap:10, marginBottom: 10}}>
          <input
            className="mono"
            value={sourceUrl}
            onChange={e => setSourceUrl(e.target.value)}
            placeholder="https://example.com/openapi.json"
          />
          <button onClick={loadFromUrl} disabled={loadingUrl}>
            {loadingUrl ? 'Loading...' : 'Load URL'}
          </button>
        </div>

        <textarea
          className="mono modalTextarea"
          ref={pasteTextareaRef}
          value={pasteText}
          onChange={e => setPasteText(e.target.value)}
          onKeyDown={e => {
            if ((e.ctrlKey || e.metaKey) && e.key === 'Enter') submitPasted()
          }}
          placeholder="Paste JSON/YAML here..."
        />

        {pasteError && (
          <div className="small" style={{ color: '#ff9a9a', marginTop: 8 }}>
            {pasteError}
          </div>
        )}

        <div className="modalActions">
          <button onClick={pasteFromClipboard} disabled={!canReadClipboard} title={!canReadClipboard ? 'Unavailable without a secure context (https/localhost) and permissions' : undefined}>
            Paste from clipboard
          </button>
          <button onClick={submitPasted}>Import</button>
        </div>
      </dialog>
    </div>
  )
}

import type { Collection, Folder, HttpMethod, RequestItem, RequestParam } from '../../collectionTree'
import { uid } from '../../../shared/utils/id'
import { isAbsoluteUrl } from '../../../shared/utils/url'

const METHODS: HttpMethod[] = ['GET', 'POST', 'PUT', 'PATCH', 'DELETE', 'HEAD', 'OPTIONS']

type InsomniaHeader = { name?: unknown, value?: unknown, disabled?: unknown }
type InsomniaParameter = { name?: unknown, value?: unknown, disabled?: unknown }

type InsomniaRequestNode = {
  url?: unknown
  name?: unknown
  method?: unknown
  body?: unknown
  headers?: unknown
  parameters?: unknown
}

type InsomniaFolderNode = {
  name?: unknown
  children?: unknown
}

type InsomniaExportV5 = {
  type?: unknown
  name?: unknown
  collection?: unknown
  environments?: unknown
}

export function isInsomniaExport(doc: any): boolean {
  const type = typeof doc?.type === 'string' ? doc.type : ''
  if (type.startsWith('collection.insomnia.rest/')) return true

  // legacy Insomnia export format
  if (Array.isArray(doc?.resources) && doc.resources.some((r: any) => r?._type === 'request' || r?._type === 'request_group')) {
    return true
  }

  return false
}

function normalizeName(value: any, fallback: string) {
  const n = typeof value === 'string' ? value.trim() : ''
  return n || fallback
}

function toHttpMethod(maybe: any): HttpMethod | null {
  const m = typeof maybe === 'string' ? maybe.trim().toUpperCase() : ''
  if (!m) return null
  if ((METHODS as string[]).includes(m)) return m as HttpMethod
  return null
}

function toHeaderMap(headers: any): Record<string, string> {
  const out: Record<string, string> = {}
  if (!Array.isArray(headers)) return out
  for (const h of headers as InsomniaHeader[]) {
    if (!h || typeof h !== 'object') continue
    if ((h as any).disabled) continue
    const key = typeof h.name === 'string' ? h.name.trim() : ''
    if (!key) continue
    const value = typeof h.value === 'string' ? h.value : ''
    out[key] = value
  }
  return out
}

function stripQueryAndHash(raw: string) {
  const hashIdx = raw.indexOf('#')
  const beforeHash = hashIdx >= 0 ? raw.slice(0, hashIdx) : raw
  const qIdx = beforeHash.indexOf('?')
  return qIdx >= 0 ? beforeHash.slice(0, qIdx) : beforeHash
}

function extractPathFromInsomniaUrl(rawUrl: string) {
  let s = rawUrl.trim()
  if (!s) return '/'

  s = stripQueryAndHash(s)

  // {{baseUrl}}/path
  const m = s.match(/^\{\{\s*baseUrl\s*\}\}(.*)$/)
  if (m) {
    const after = (m[1] || '').trim()
    const out = after.startsWith('/') ? after : after ? `/${after}` : '/'
    return out || '/'
  }

  if (s.startsWith('/')) return s

  if (isAbsoluteUrl(s) && !s.includes('{{')) {
    try {
      const u = new URL(s)
      return u.pathname || '/'
    } catch {
      // fall through
    }
  }

  const idx = s.indexOf('://')
  if (idx >= 0) {
    const afterScheme = s.slice(idx + 3)
    const slash = afterScheme.indexOf('/')
    if (slash >= 0) return '/' + afterScheme.slice(slash + 1)
    return '/'
  }

  const firstSlash = s.indexOf('/')
  if (firstSlash >= 0) return s.slice(firstSlash)

  return '/'
}

function parseQueryParams(params: any): RequestParam[] {
  if (!Array.isArray(params)) return []

  const out: RequestParam[] = []
  for (const p of params as InsomniaParameter[]) {
    if (!p || typeof p !== 'object') continue
    const name = typeof p.name === 'string' ? p.name.trim() : ''
    if (!name) continue
    const value = typeof p.value === 'string' ? p.value : ''
    out.push({ name, in: 'query', example: value })
  }
  return out
}

function parseBody(body: any) {
  if (!body || typeof body !== 'object') return undefined
  const mimeType = typeof (body as any).mimeType === 'string' ? (body as any).mimeType.trim() : ''
  const text = typeof (body as any).text === 'string' ? (body as any).text : ''
  if (!mimeType && !text) return undefined
  return { contentType: mimeType || 'text/plain', example: text }
}

function buildRequestFromNode(node: InsomniaRequestNode): RequestItem | null {
  const method = toHttpMethod(node.method)
  if (!method) return null

  const rawUrl = typeof node.url === 'string' ? node.url.trim() : ''
  const urlTemplate = rawUrl || '{{baseUrl}}/'

  const name = normalizeName(node.name, `${method}`)
  const headers = toHeaderMap(node.headers)
  const body = parseBody(node.body)

  const params = parseQueryParams(node.parameters)
  const path = extractPathFromInsomniaUrl(urlTemplate)

  const out: RequestItem = {
    id: uid('req'),
    name,
    method,
    path,
    urlTemplate,
    params,
    headers,
    body,
  }

  if (out.body?.contentType) {
    const hasCt = Object.keys(out.headers).some(k => k.toLowerCase() === 'content-type')
    if (!hasCt) out.headers = { ...out.headers, 'Content-Type': out.body.contentType }
  }

  // ensure path params are represented
  out.path.replaceAll(/\{([^}]+)\}/g, (_m: string, name: string) => {
    if (!out.params.some(p => p.in === 'path' && p.name === name)) {
      out.params.push({ name, in: 'path', required: true })
    }
    return _m
  })

  return out
}

function buildFolderFromNode(node: InsomniaFolderNode): Folder {
  const name = normalizeName(node.name, 'Folder')
  const children: any[] = Array.isArray(node.children) ? (node.children as any[]) : []

  const folders: Folder[] = []
  const requests: RequestItem[] = []

  for (const child of children) {
    if (!child || typeof child !== 'object') continue

    if (Array.isArray((child as any).children)) {
      folders.push(buildFolderFromNode(child as any))
      continue
    }

    const req = buildRequestFromNode(child as any)
    if (req) requests.push(req)
  }

  return { id: uid('folder'), name, requests, folders }
}

function parseVariablesFromV5(doc: InsomniaExportV5): Record<string, string> | undefined {
  const env = doc.environments
  const data = env && typeof env === 'object' ? (env as any).data : undefined
  if (!data || typeof data !== 'object') return undefined

  const out: Record<string, string> = {}
  for (const [k, v] of Object.entries(data)) {
    const key = k.trim()
    if (!key) continue
    out[key] = typeof v === 'string' ? v : JSON.stringify(v)
  }
  return Object.keys(out).length ? out : undefined
}

export function buildCollectionFromInsomnia(doc: any, nameOverride?: string): Collection {
  const name = (nameOverride || normalizeName(doc?.name, 'Imported Insomnia')).trim()

  // Insomnia v5 export: nested `collection` tree
  if (Array.isArray(doc?.collection)) {
    const folders: Folder[] = []
    const rootRequests: RequestItem[] = []

    const collectionNodes = doc.collection as any[]
    let topNodes: any[] = collectionNodes

    // Common Insomnia v5 export shape: a single root folder that duplicates the collection name.
    // Unwrap it to avoid "folder inside same-named folder".
    if (collectionNodes.length === 1) {
      const only = collectionNodes[0]
      if (only && typeof only === 'object' && Array.isArray((only as any).children)) {
        const onlyName = normalizeName((only as any).name, '')
        const docName = normalizeName(doc?.name, '')
        if (onlyName && (onlyName === name || onlyName === docName)) {
          topNodes = (only as any).children as any[]
        }
      }
    }

    for (const node of topNodes) {
      if (!node || typeof node !== 'object') continue
      if (Array.isArray((node as any).children)) {
        folders.push(buildFolderFromNode(node as any))
        continue
      }
      const req = buildRequestFromNode(node as any)
      if (req) rootRequests.push(req)
    }

    if (rootRequests.length) {
      folders.unshift({ id: uid('folder'), name: 'root', requests: rootRequests, folders: [] })
    }

    return {
      id: uid('col'),
      name,
      variables: parseVariablesFromV5(doc),
      folders,
    }
  }

  // Legacy export format not implemented (yet)
  throw new Error('Unsupported Insomnia export format (expected a v5 collection file).')
}

function guessBaseUrl(swagger2: any): string | undefined {
  const host = typeof swagger2?.host === 'string' ? swagger2.host.trim() : ''
  const basePath = typeof swagger2?.basePath === 'string' ? swagger2.basePath.trim() : ''
  const schemes: any[] = Array.isArray(swagger2?.schemes) ? swagger2.schemes : []

  if (!host) return undefined
  const scheme = typeof schemes[0] === 'string' ? schemes[0] : 'https'
  const bp = basePath ? (basePath.startsWith('/') ? basePath : `/${basePath}`) : ''
  return `${scheme}://${host}${bp}`
}

function normalizeConsumes(consumes: any): string[] {
  if (!Array.isArray(consumes)) return []
  return consumes.filter(x => typeof x === 'string' && x.trim()).map(x => x.trim())
}

function swagger2ParamsToV3(opOrPathItem: any): any[] {
  const params = Array.isArray(opOrPathItem?.parameters) ? opOrPathItem.parameters : []
  return params.filter(Boolean)
}

function resolveRef(doc: any, ref: string): any {
  if (typeof ref !== 'string' || !ref.startsWith('#/')) return undefined
  const parts = ref.slice(2).split('/').filter(Boolean).map(p => p.replaceAll('~1', '/').replaceAll('~0', '~'))
  let cur: any = doc
  for (const part of parts) {
    if (!cur || typeof cur !== 'object') return undefined
    cur = cur[part]
  }
  return cur
}

function exampleFromSwagger2SchemaShallow(schema: any, doc: any, depth = 0): any {
  if (!schema || typeof schema !== 'object') return undefined
  if (depth > 6) return undefined

  if (typeof schema.$ref === 'string') {
    const resolved = resolveRef(doc, schema.$ref)
    if (resolved) return exampleFromSwagger2SchemaShallow(resolved, doc, depth + 1)
  }

  if (schema.example !== undefined) return schema.example
  if (schema['x-example'] !== undefined) return schema['x-example']
  if (schema.default !== undefined) return schema.default
  if (schema.const !== undefined) return schema.const
  if (Array.isArray(schema.enum) && schema.enum.length) return schema.enum[0]

  return undefined
}

function exampleFromSwagger2BodyParam(bodyParam: any, doc: any): any {
  if (!bodyParam || typeof bodyParam !== 'object') return undefined
  if (bodyParam.example !== undefined) return bodyParam.example
  if (bodyParam['x-example'] !== undefined) return bodyParam['x-example']
  if (bodyParam.schema) return exampleFromSwagger2SchemaShallow(bodyParam.schema, doc)
  return undefined
}

function buildRequestBodyFromSwagger2Params(params: any[], consumes: string[], doc: any) {
  const ct =
    consumes.find(x => x === 'application/json') ||
    consumes[0] ||
    'application/json'

  const bodyParam = params.find(p => p?.in === 'body' && p?.schema)
  if (bodyParam?.schema) {
    const example = exampleFromSwagger2BodyParam(bodyParam, doc)
    return {
      content: {
        [ct]: example === undefined ? { schema: bodyParam.schema } : { schema: bodyParam.schema, example },
      },
    }
  }

  const formParams = params.filter(p => p?.in === 'formData' && typeof p?.name === 'string' && p.name)
  if (formParams.length) {
    const props: Record<string, any> = {}
    for (const p of formParams) {
      const ex = p.example ?? p['x-example']
      props[p.name] = ex === undefined ? { type: p.type || 'string' } : { type: p.type || 'string', example: ex }
    }

    const formCt =
      consumes.find(x => x === 'multipart/form-data') ||
      consumes.find(x => x === 'application/x-www-form-urlencoded') ||
      ct

    return {
      content: {
        [formCt]: { schema: { type: 'object', properties: props }, example: {} },
      },
    }
  }

  return undefined
}

function swagger2ParamToV3Param(p: any) {
  if (!p || typeof p !== 'object') return undefined
  if (p.in !== 'path' && p.in !== 'query' && p.in !== 'header') return undefined
  if (typeof p.name !== 'string' || !p.name) return undefined

  const required = p.in === 'path' ? true : !!p.required
  const schema =
    p.schema && typeof p.schema === 'object'
      ? p.schema
      : { type: p.type || 'string' }

  // Swagger 2 non-body params often put `enum` on the parameter itself.
  if (!Array.isArray(schema.enum) && Array.isArray(p.enum) && p.enum.length) {
    schema.enum = p.enum
  }

  return {
    name: p.name,
    in: p.in,
    required,
    schema,
    example: p.example,
  }
}

function swagger2ToV3Like(swagger2: any): any {
  const baseUrl = guessBaseUrl(swagger2)
  const globalConsumes = normalizeConsumes(swagger2?.consumes)

  const outPaths: Record<string, any> = {}
  const paths = swagger2?.paths && typeof swagger2.paths === 'object' ? swagger2.paths : {}

  for (const path of Object.keys(paths)) {
    const pathItem = paths[path]
    if (!pathItem || typeof pathItem !== 'object') continue

    const pathLevelParams = swagger2ParamsToV3(pathItem)

    const v3PathItem: Record<string, any> = {}
    for (const method of Object.keys(pathItem)) {
      if (method === 'parameters') continue
      const op = pathItem[method]
      if (!op || typeof op !== 'object') continue

      const consumes = normalizeConsumes(op?.consumes)
      const ctList = consumes.length ? consumes : globalConsumes

      const opParams = swagger2ParamsToV3(op)
      const mergedParams = [...pathLevelParams, ...opParams]

      const requestBody = buildRequestBodyFromSwagger2Params(mergedParams, ctList, swagger2)
      const parameters = mergedParams
        .map(swagger2ParamToV3Param)
        .filter(Boolean)

      v3PathItem[method] = {
        summary: op.summary,
        operationId: op.operationId,
        tags: Array.isArray(op.tags) ? op.tags : undefined,
        parameters: parameters.length ? parameters : undefined,
        requestBody,
      }
    }

    outPaths[path] = v3PathItem
  }

  return {
    openapi: '3.0.0',
    servers: baseUrl ? [{ url: baseUrl }] : undefined,
    paths: outPaths,
  }
}

export async function normalizeToV3(api: any): Promise<any> {
  if (typeof api?.openapi === 'string' && api.openapi.startsWith('3.')) return api
  if (api?.swagger === '2.0') return swagger2ToV3Like(api)
  return api
}

import { parse as parseYaml } from 'yaml'
import { normalizeToV3 } from './normalizeToV3'

export function parseJsonOrYaml(text: string): any {
  const trimmed = text.trim()
  if (!trimmed) throw new Error('Empty spec')

  try {
    return JSON.parse(trimmed)
  } catch {
    // ignore
  }

  try {
    return parseYaml(trimmed)
  } catch (e: any) {
    throw new Error(e?.message || 'Invalid YAML/JSON')
  }
}

function decodeJsonPointerToken(token: string) {
  return token.replaceAll('~1', '/').replaceAll('~0', '~')
}

function getByJsonPointer(root: any, ref: string): any {
  if (ref === '#') return root
  if (!ref.startsWith('#/')) return undefined

  const parts = ref
    .slice(2)
    .split('/')
    .map(decodeJsonPointerToken)

  let cur = root
  for (const p of parts) {
    if (cur && typeof cur === 'object' && p in cur) cur = (cur as any)[p]
    else return undefined
  }
  return cur
}

function dereferenceLocalRefs(root: any): any {
  const cache = new Map<string, any>()
  const inProgress = new Set<string>()

  function walk(node: any): any {
    if (!node || typeof node !== 'object') return node
    if (Array.isArray(node)) return node.map(walk)

    const ref = (node as any).$ref
    if (typeof ref === 'string' && ref.startsWith('#/')) {
      const { $ref: _omit, ...rest } = node as any

      if (cache.has(ref)) {
        const cached = cache.get(ref)
        return Object.keys(rest).length ? { ...cached, ...walk(rest) } : cached
      }
      if (inProgress.has(ref)) return node

      const target = getByJsonPointer(root, ref)
      if (target === undefined) return node

      inProgress.add(ref)
      const resolved = walk(target)
      inProgress.delete(ref)

      cache.set(ref, resolved)
      return Object.keys(rest).length ? { ...resolved, ...walk(rest) } : resolved
    }

    const out: Record<string, any> = {}
    for (const [k, v] of Object.entries(node)) out[k] = walk(v)
    return out
  }

  return walk(root)
}

export async function loadOpenApiFromText(text: string) {
  const parsed = parseJsonOrYaml(text)
  const deref = dereferenceLocalRefs(parsed)
  return normalizeToV3(deref)
}

import type { Collection, Folder, HttpMethod, RequestItem, RequestParam } from '../../collectionTree'
import { uid } from '../../../shared/utils/id'
import { isAbsoluteUrl } from '../../../shared/utils/url'

const METHODS: HttpMethod[] = ['GET', 'POST', 'PUT', 'PATCH', 'DELETE', 'HEAD', 'OPTIONS']

export function isPostmanCollection(doc: any): boolean {
  const schema = doc?.info?.schema
  if (typeof schema === 'string' && schema.includes('schema.getpostman.com/json/collection/')) return true
  if (doc?.info?._postman_id && Array.isArray(doc?.item)) return true
  return false
}

function parseVariables(vars: any): Record<string, string> | undefined {
  if (!Array.isArray(vars)) return undefined
  const out: Record<string, string> = {}
  for (const v of vars) {
    const key = typeof v?.key === 'string' ? v.key.trim() : ''
    if (!key) continue
    const value = typeof v?.value === 'string' ? v.value : ''
    out[key] = value
  }
  return Object.keys(out).length ? out : undefined
}

function normalizeName(value: any, fallback: string) {
  const n = typeof value === 'string' ? value.trim() : ''
  return n || fallback
}

function toHttpMethod(maybe: any): HttpMethod | null {
  const m = typeof maybe === 'string' ? maybe.trim().toUpperCase() : ''
  if (!m) return null
  if ((METHODS as string[]).includes(m)) return m as HttpMethod
  return null
}

function toHeaderMap(headers: any): Record<string, string> {
  const out: Record<string, string> = {}
  if (!Array.isArray(headers)) return out
  for (const h of headers) {
    if (!h || typeof h !== 'object') continue
    if (h.disabled) continue
    const key = typeof h.key === 'string' ? h.key.trim() : ''
    if (!key) continue
    const value = typeof h.value === 'string' ? h.value : ''
    out[key] = value
  }
  return out
}

function getHeaderCaseInsensitive(headers: Record<string, string>, name: string): string | undefined {
  const needle = name.toLowerCase()
  for (const [k, v] of Object.entries(headers)) {
    if (k.toLowerCase() === needle) return v
  }
  return undefined
}

function replaceColonPathParams(path: string) {
  return path.replaceAll(/\/:([A-Za-z0-9_]+)/g, '/{$1}')
}

function stripQuery(raw: string) {
  const i = raw.indexOf('?')
  return i >= 0 ? raw.slice(0, i) : raw
}

function extractPathFromRawUrl(raw: string): string {
  let s = raw.trim()
  if (!s) return '/'

  s = stripQuery(s)

  if (s.startsWith('{{')) {
    const end = s.indexOf('}}')
    if (end >= 0) {
      const after = s.slice(end + 2)
      if (after.startsWith('/')) s = after
    }
  }

  if (s.startsWith('/')) return s

  if (isAbsoluteUrl(s) && !s.includes('{{')) {
    try {
      const u = new URL(s)
      return u.pathname || '/'
    } catch {
      // fall through
    }
  }

  const idx = s.indexOf('://')
  if (idx >= 0) {
    const afterScheme = s.slice(idx + 3)
    const slash = afterScheme.indexOf('/')
    if (slash >= 0) return '/' + afterScheme.slice(slash + 1)
    return '/'
  }

  const firstSlash = s.indexOf('/')
  if (firstSlash >= 0) return s.slice(firstSlash)

  return '/'
}

function isNumericSegment(s: string) {
  return /^\d+$/.test(s)
}

function toCamelCase(s: string) {
  const parts = s.split(/[-_]+/g).filter(Boolean)
  if (!parts.length) return s
  return parts[0].toLowerCase() + parts.slice(1).map(p => (p ? p[0].toUpperCase() + p.slice(1) : '')).join('')
}

function suggestParamName(prevSegment: string | undefined, used: Set<string>) {
  const prev = (prevSegment || '').trim()
  let base = 'id'
  if (prev && /^[A-Za-z][A-Za-z0-9_-]*$/.test(prev)) {
    const singular = prev.endsWith('s') && prev.length > 1 ? prev.slice(0, -1) : prev
    base = `${toCamelCase(singular)}Id`
  }

  if (!used.has(base)) return base

  let i = 2
  while (used.has(`${base}${i}`)) i++
  return `${base}${i}`
}

function inferPathParamsFromConcreteSegments(path: string, params: RequestParam[]) {
  const segments = path.split('/').filter(Boolean)
  if (!segments.length) return { path, params }

  const used = new Set(params.filter(p => p.in === 'path').map(p => p.name))
  const outSegments = [...segments]
  const outParams = [...params]

  for (let i = 0; i < segments.length; i++) {
    const seg = segments[i]
    if (!seg) continue
    if (seg.startsWith('{') && seg.endsWith('}')) continue
    if (!isNumericSegment(seg)) continue

    const name = suggestParamName(segments[i - 1], used)
    used.add(name)
    outSegments[i] = `{${name}}`
    if (!outParams.some(p => p.in === 'path' && p.name === name)) {
      outParams.push({ name, in: 'path', required: true, example: seg })
    }
  }

  return { path: '/' + outSegments.join('/'), params: outParams }
}

function parseUrl(url: any): { path: string, params: RequestParam[] } {
  const params: RequestParam[] = []

  const raw =
    typeof url === 'string'
      ? url
      : typeof url?.raw === 'string'
        ? url.raw
        : ''

  let path = extractPathFromRawUrl(raw)
  if ((!path || path === '/') && raw.trim() === '' && Array.isArray(url?.path) && url.path.length) {
    const segments = url.path.filter((s: any) => typeof s === 'string' && s.trim()).map((s: string) => s.trim())
    path = '/' + segments.join('/')
  }
  path = replaceColonPathParams(path)
  if (!path.startsWith('/')) path = `/${path}`

  const urlVars: any[] = Array.isArray(url?.variable) ? url.variable : []
  for (const v of urlVars) {
    if (!v || typeof v !== 'object') continue
    const name = typeof v.key === 'string' ? v.key.trim() : ''
    if (!name) continue
    if (params.some(p => p.in === 'path' && p.name === name)) continue
    params.push({ name, in: 'path', required: true, example: v.value })
  }

  const query: any[] = Array.isArray(url?.query) ? url.query : []
  for (const q of query) {
    if (!q || typeof q !== 'object') continue
    if (q.disabled) continue
    const name = typeof q.key === 'string' ? q.key.trim() : ''
    if (!name) continue
    if (params.some(p => p.in === 'query' && p.name === name)) continue
    const example = typeof q.value === 'string' ? q.value : undefined
    params.push({ name, in: 'query', example })
  }

  // ensure path params are represented even if they weren't listed in url.variable
  path.replaceAll(/\{([^}]+)\}/g, (_m: string, name: string) => {
    if (!params.some(p => p.in === 'path' && p.name === name)) {
      params.push({ name, in: 'path', required: true })
    }
    return _m
  })

  const inferred = inferPathParamsFromConcreteSegments(path, params)
  return { path: inferred.path, params: inferred.params }
}

function parseBody(body: any, headers: Record<string, string>) {
  if (!body || typeof body !== 'object') return undefined

  const mode = typeof body.mode === 'string' ? body.mode : ''
  const headerCt = (getHeaderCaseInsensitive(headers, 'Content-Type') || '').trim()

  if (mode === 'raw') {
    const raw = typeof body.raw === 'string' ? body.raw : ''
    const language = body?.options?.raw?.language
    const ct =
      headerCt ||
      (language === 'json' ? 'application/json' : 'text/plain')

    if (ct.toLowerCase().includes('json')) {
      try {
        const parsed = JSON.parse(raw)
        return { contentType: ct, example: parsed }
      } catch {
        return { contentType: ct, example: raw }
      }
    }

    return { contentType: ct, example: raw }
  }

  if (mode === 'formdata') {
    const fields: any[] = Array.isArray(body.formdata) ? body.formdata : []
    const exampleObj: Record<string, string> = {}
    for (const f of fields) {
      if (!f || typeof f !== 'object') continue
      if (f.disabled) continue
      if (f.type === 'file') continue
      const key = typeof f.key === 'string' ? f.key.trim() : ''
      if (!key) continue
      const value = typeof f.value === 'string' ? f.value : ''
      exampleObj[key] = value
    }
    return { contentType: headerCt || 'multipart/form-data', example: exampleObj }
  }

  if (mode === 'file') {
    return { contentType: headerCt || 'application/octet-stream', example: '' }
  }

  return undefined
}

function buildRequestFromItem(item: any): RequestItem | null {
  const req = item?.request
  if (!req || typeof req !== 'object') return null

  const method = toHttpMethod(req.method)
  if (!method) return null

  const name = normalizeName(item?.name, `${method}`)

  const headers = toHeaderMap(req.header)
  const { path, params } = parseUrl(req.url)
  const body = parseBody(req.body, headers)

  const urlTemplate = `{{baseUrl}}${path.startsWith('/') ? '' : '/'}${path}`

  return {
    id: uid('req'),
    name,
    method,
    path,
    urlTemplate,
    params,
    headers,
    body,
  }
}

function buildFolderFromGroup(group: any): Folder {
  const name = normalizeName(group?.name, 'Folder')
  const children: any[] = Array.isArray(group?.item) ? group.item : []

  const folders: Folder[] = []
  const requests: RequestItem[] = []

  for (const child of children) {
    if (child && typeof child === 'object' && Array.isArray(child.item) && !child.request) {
      folders.push(buildFolderFromGroup(child))
      continue
    }
    const req = buildRequestFromItem(child)
    if (req) requests.push(req)
  }

  return {
    id: uid('folder'),
    name,
    requests,
    folders,
  }
}

export function buildCollectionFromPostman(postman: any, nameOverride?: string): Collection {
  const name = (nameOverride || normalizeName(postman?.info?.name, 'Imported Postman')).trim()
  const variables = parseVariables(postman?.variable)

  const topItems: any[] = Array.isArray(postman?.item) ? postman.item : []
  const folders: Folder[] = []
  const rootRequests: RequestItem[] = []

  for (const it of topItems) {
    if (it && typeof it === 'object' && Array.isArray(it.item) && !it.request) {
      folders.push(buildFolderFromGroup(it))
      continue
    }
    const req = buildRequestFromItem(it)
    if (req) rootRequests.push(req)
  }

  if (rootRequests.length) {
    folders.unshift({ id: uid('folder'), name: 'root', requests: rootRequests, folders: [] })
  }

  return {
    id: uid('col'),
    name,
    variables,
    folders,
  }
}

import { useEffect, useRef, useState } from 'react'
import { VariableAutocompleteField } from '../../../shared/components/VariableAutocompleteField'
import type { VariableSuggestion } from '../../../shared/utils/variables'

type AuthType = 'none' | 'basic' | 'bearer'

function parseAuthorization(raw: string): { type: AuthType; username: string; password: string; token: string } {
  const value = (raw || '').trim()
  if (!value) return { type: 'none', username: '', password: '', token: '' }

  const basicMatch = value.match(/^basic\s+(.+)$/i)
  if (basicMatch) {
    const decoded = safeBase64Decode(basicMatch[1].trim())
    const idx = decoded.indexOf(':')
    if (idx >= 0) return { type: 'basic', username: decoded.slice(0, idx), password: decoded.slice(idx + 1), token: '' }
    return { type: 'basic', username: decoded, password: '', token: '' }
  }

  const bearerMatch = value.match(/^bearer\s+(.+)$/i)
  if (bearerMatch) return { type: 'bearer', username: '', password: '', token: bearerMatch[1].trim() }

  // Unknown format: keep it editable as a bearer token payload.
  return { type: 'bearer', username: '', password: '', token: value }
}

function safeBase64EncodeUtf8(input: string) {
  try {
    const bytes = new TextEncoder().encode(input)
    let bin = ''
    const chunkSize = 0x8000
    for (let i = 0; i < bytes.length; i += chunkSize) {
      const chunk = bytes.subarray(i, i + chunkSize)
      bin += String.fromCharCode(...chunk)
    }
    return btoa(bin)
  } catch {
    try {
      return btoa(input)
    } catch {
      return ''
    }
  }
}

function safeBase64Decode(input: string) {
  try {
    const bin = atob(input)
    const bytes = Uint8Array.from(bin, c => c.charCodeAt(0))
    return new TextDecoder().decode(bytes)
  } catch {
    try {
      return atob(input)
    } catch {
      return ''
    }
  }
}

export function AuthorizationTab(props: {
  value: string
  onChangeValue: (next: string) => void
  variableSuggestions: VariableSuggestion[]
}) {
  const menuWrapRef = useRef<HTMLDivElement | null>(null)
  const [menuOpen, setMenuOpen] = useState(false)

  const [{ type, username, password, token }, setState] = useState(() => parseAuthorization(props.value))

  useEffect(() => {
    const next = parseAuthorization(props.value)
    setState(prev => {
      if (
        prev.type === next.type &&
        prev.username === next.username &&
        prev.password === next.password &&
        prev.token === next.token
      ) return prev
      return next
    })
  }, [props.value])

  useEffect(() => {
    if (!menuOpen) return

    function onPointerDown(e: PointerEvent) {
      const t = e.target as Node | null
      const wrap = menuWrapRef.current
      if (t && wrap && wrap.contains(t)) return
      setMenuOpen(false)
    }

    function onKeyDown(e: KeyboardEvent) {
      if (e.key === 'Escape') setMenuOpen(false)
    }

    window.addEventListener('pointerdown', onPointerDown)
    window.addEventListener('keydown', onKeyDown)
    return () => {
      window.removeEventListener('pointerdown', onPointerDown)
      window.removeEventListener('keydown', onKeyDown)
    }
  }, [menuOpen])

  function setType(nextType: AuthType) {
    setState(prev => {
      const next = { ...prev, type: nextType }
      if (nextType === 'none') {
        props.onChangeValue('')
        return { type: 'none', username: '', password: '', token: '' }
      }
      if (nextType === 'basic') {
        const hasAny = !!(next.username.trim() || next.password)
        props.onChangeValue(hasAny ? `Basic ${safeBase64EncodeUtf8(`${next.username}:${next.password}`)}` : '')
        return next
      }
      if (nextType === 'bearer') {
        props.onChangeValue(next.token.trim() ? `Bearer ${next.token}` : '')
        return next
      }
      return next
    })
  }

  function setUsername(nextUsername: string) {
    setState(prev => {
      const next = { ...prev, username: nextUsername, type: 'basic' as const }
      const hasAny = !!(next.username.trim() || next.password)
      props.onChangeValue(hasAny ? `Basic ${safeBase64EncodeUtf8(`${next.username}:${next.password}`)}` : '')
      return next
    })
  }

  function setPassword(nextPassword: string) {
    setState(prev => {
      const next = { ...prev, password: nextPassword, type: 'basic' as const }
      const hasAny = !!(next.username.trim() || next.password)
      props.onChangeValue(hasAny ? `Basic ${safeBase64EncodeUtf8(`${next.username}:${next.password}`)}` : '')
      return next
    })
  }

  function setToken(nextToken: string) {
    setState(prev => {
      const next = { ...prev, token: nextToken, type: 'bearer' as const }
      props.onChangeValue(next.token.trim() ? `Bearer ${next.token}` : '')
      return next
    })
  }

  const typeLabel = type === 'basic' ? 'Basic Auth' : type === 'bearer' ? 'Bearer Token' : 'None'

  return (
    <div className="accordion authAccordion">
      <div className="section">
        <div className="formRow">
          <div className="formLabel mono">Authorization</div>
          <div ref={menuOpen ? menuWrapRef : null} className="selectMenuWrap" style={{ minWidth: 180 }}>
            <button
              type="button"
              className="selectMenuBtn"
              onPointerDown={e => e.stopPropagation()}
              onClick={e => {
                e.preventDefault()
                e.stopPropagation()
                setMenuOpen(v => !v)
              }}
              aria-haspopup="menu"
              aria-expanded={menuOpen}
              aria-label="Authorization type"
              title="Authorization type"
            >
              {typeLabel}
            </button>

            {menuOpen ? (
              <div
                className="selectMenuPanel"
                role="menu"
                onPointerDown={e => {
                  e.preventDefault()
                  e.stopPropagation()
                }}
                onClick={e => {
                  e.preventDefault()
                  e.stopPropagation()
                }}
              >
                <button
                  type="button"
                  className={`selectMenuItem ${type === 'basic' ? 'selectMenuItemActive' : ''}`}
                  role="menuitem"
                  onClick={() => {
                    setMenuOpen(false)
                    setType('basic')
                  }}
                >
                  Basic Auth
                </button>
                <button
                  type="button"
                  className={`selectMenuItem ${type === 'bearer' ? 'selectMenuItemActive' : ''}`}
                  role="menuitem"
                  onClick={() => {
                    setMenuOpen(false)
                    setType('bearer')
                  }}
                >
                  Bearer Token
                </button>
                <button
                  type="button"
                  className={`selectMenuItem ${type === 'none' ? 'selectMenuItemActive' : ''}`}
                  role="menuitem"
                  onClick={() => {
                    setMenuOpen(false)
                    setType('none')
                  }}
                >
                  None
                </button>
              </div>
            ) : null}
          </div>
        </div>

        {type === 'basic' ? (
          <>
            <div className="formRow">
              <div className="formLabel mono">Username</div>
              <VariableAutocompleteField
                className="mono"
                value={username}
                suggestions={props.variableSuggestions}
                onChangeValue={setUsername}
                placeholder="Username"
                autoComplete="off"
                autoCorrect="off"
                autoCapitalize="none"
                spellCheck={false}
              />
            </div>
            <div className="formRow">
              <div className="formLabel mono">Password</div>
              <VariableAutocompleteField
                className="mono"
                type="password"
                value={password}
                suggestions={props.variableSuggestions}
                onChangeValue={setPassword}
                placeholder="Password"
                autoComplete="off"
                autoCorrect="off"
                autoCapitalize="none"
                spellCheck={false}
              />
            </div>
          </>
        ) : null}

        {type === 'bearer' ? (
          <div className="formRow">
            <div className="formLabel mono">Token</div>
            <VariableAutocompleteField
              className="mono"
              value={token}
              suggestions={props.variableSuggestions}
              onChangeValue={setToken}
              placeholder="Bearer token…"
              autoComplete="off"
              autoCorrect="off"
              autoCapitalize="none"
              spellCheck={false}
            />
          </div>
        ) : null}
      </div>
    </div>
  )
}

import { useEffect, useMemo, useRef, useState, type Dispatch, type ReactNode, type RefObject, type SetStateAction } from 'react'
