              </button>
          </summary>
          {renderFilePicker()}
        </details>
      )}

      {bodyFormatMenuOpen ? (
        <div
          ref={bodyFormatMenuPanelRef}
          className="selectMenuPanel"
          role="menu"
          style={{ position: 'fixed', left: bodyFormatMenuAnchor.left, top: bodyFormatMenuAnchor.top, width: bodyFormatMenuAnchor.width, zIndex: 200 }}
          onPointerDown={e => {
            e.preventDefault()
            e.stopPropagation()
          }}
          onClick={e => {
            e.preventDefault()
            e.stopPropagation()
          }}
        >
          {(['auto', 'json', 'xml', 'yaml', 'text'] as BodyFormat[]).map(v => (
            <button
              key={v}
              type="button"
              className={`selectMenuItem ${bodyFormat === v ? 'selectMenuItemActive' : ''}`}
              role="menuitem"
              onClick={() => pickBodyFormat(v)}
            >
              {labelForBodyFormat(v)}
            </button>
          ))}
        </div>
      ) : null}
    </div>
  )
}

import type { RequestDraft } from '../../../shared/types/requestHistory'
import { safeParseJson } from './json'

const REQUEST_DRAFTS_KEY = 'ruf_request_drafts_v1'

export function loadRequestDraft(requestId: string): RequestDraft | null {
  const parsed = safeParseJson<any>(localStorage.getItem(REQUEST_DRAFTS_KEY))
  if (!parsed || typeof parsed !== 'object') return null
  const draft = (parsed as any)[requestId]
  if (!draft || typeof draft !== 'object') return null
  return draft as RequestDraft
}

export function saveRequestDraft(requestId: string, draft: RequestDraft) {
  const parsed = safeParseJson<any>(localStorage.getItem(REQUEST_DRAFTS_KEY))
  const next = parsed && typeof parsed === 'object' ? parsed : {}
  next[requestId] = draft
  localStorage.setItem(REQUEST_DRAFTS_KEY, JSON.stringify(next))
}

import { safeParseJson } from './json'

const VALUE_HISTORY_KEY = 'ruf_value_history_v1'

export type ValueHistoryKind = 'header' | 'query' | 'path'
export type ValueHistoryStore = Record<ValueHistoryKind, Record<string, string[]>>

export function loadValueHistory(): ValueHistoryStore {
  const parsed = safeParseJson<any>(localStorage.getItem(VALUE_HISTORY_KEY))
  const empty: ValueHistoryStore = { header: {}, query: {}, path: {} }
  if (!parsed || typeof parsed !== 'object') return empty
  const obj = parsed as Partial<ValueHistoryStore>
  return {
    header: obj.header && typeof obj.header === 'object' ? obj.header : {},
    query: obj.query && typeof obj.query === 'object' ? obj.query : {},
    path: obj.path && typeof obj.path === 'object' ? obj.path : {},
  }
}

export function saveValueHistory(store: ValueHistoryStore) {
  localStorage.setItem(VALUE_HISTORY_KEY, JSON.stringify(store))
}

export function addValueHistoryEntry(
  prev: ValueHistoryStore,
  kind: ValueHistoryKind,
  keyRaw: string,
  valueRaw: string,
  maxItems = 10,
): ValueHistoryStore {
  const key = keyRaw.trim()
  const value = valueRaw.trim()
  if (!key || !value) return prev

  const prevByKind = prev[kind] ?? {}
  const prevList = prevByKind[key] ?? []
  const nextList = [value, ...prevList.filter(v => v !== value)].slice(0, maxItems)
  if (prevList.length === nextList.length && prevList.every((v, i) => v === nextList[i])) return prev

  return {
    ...prev,
    [kind]: {
      ...prevByKind,
      [key]: nextList,
    },
  }
}

export function removeValueHistoryEntry(
  prev: ValueHistoryStore,
  kind: ValueHistoryKind,
  keyRaw: string,
  valueRaw: string,
): ValueHistoryStore {
  const key = keyRaw.trim()
  const value = valueRaw.trim()
  if (!key || !value) return prev

  const prevByKind = prev[kind] ?? {}
  const prevList = prevByKind[key] ?? []
  if (!prevList.length) return prev

  const nextList = prevList.filter(v => v !== value)
  if (nextList.length === prevList.length) return prev

  const nextByKind: Record<string, string[]> = { ...prevByKind }
  if (nextList.length) nextByKind[key] = nextList
  else delete nextByKind[key]

  return { ...prev, [kind]: nextByKind }
}

import type { RequestItem } from '../collectionTree'
import { isAbsoluteUrl, joinUrlParts } from '../../shared/utils/url'
import { loadAppSettings } from '../../shared/utils/appSettings'
import { resolveVariableValue } from '../../shared/utils/variables'
import { isTauri } from '../../shared/utils/tauri'
import { platformFetch } from '../../shared/utils/platformFetch'

export type RunResult = {
  ok: boolean
  status: number
  statusText: string
  timeMs: number
  requestHeadersBytes: number
  requestBodyBytes: number
  requestBytes: number
  responseHeadersBytes: number
  responseBodyBytes: number
  responseBytes: number
  requestHeaders: Record<string, string>
  responseHeaders: Record<string, string>
  bodyText: string
  file?: RunResultFile
}

export type RunResultFile = {
  fileName: string
  contentType: string
  size: number
  blob: Blob
  suppressBody: boolean
}

function byteLengthUtf8(text: string): number {
  return new TextEncoder().encode(text).length
}

function estimateHeadersBytes(headers: HeadersInit | undefined): number {
  if (!headers) return 0
  if (Array.isArray(headers)) {
    let total = 0
    for (const [k, v] of headers) total += byteLengthUtf8(`${k}: ${v}\r\n`)
    return total
  }
  if (headers instanceof Headers) {
    let total = 0
    headers.forEach((v, k) => { total += byteLengthUtf8(`${k}: ${v}\r\n`) })
    return total
  }
  let total = 0
  for (const [k, v] of Object.entries(headers)) total += byteLengthUtf8(`${k}: ${v}\r\n`)
  return total
}

function headersInitToObject(headers: HeadersInit | undefined): Record<string, string> {
  if (!headers) return {}
  if (Array.isArray(headers)) return Object.fromEntries(headers)
  if (headers instanceof Headers) {
    const out: Record<string, string> = {}
    headers.forEach((v, k) => { out[k] = v })
    return out
  }
  return { ...headers }
}

function estimateBodyBytes(body: BodyInit | null | undefined): number {
  if (!body) return 0
  if (typeof body === 'string') return byteLengthUtf8(body)
  if (body instanceof Blob) return body.size
  if (body instanceof ArrayBuffer) return body.byteLength
  if (ArrayBuffer.isView(body)) return body.byteLength
  if (body instanceof URLSearchParams) return byteLengthUtf8(body.toString())
  if (body instanceof FormData) {
    let total = 0
    for (const [k, v] of body.entries()) {
      total += byteLengthUtf8(k)
      if (typeof v === 'string') total += byteLengthUtf8(v)
      else total += v.size
    }
    return total
  }
  return 0
}

function maybeProxyUrl(url: string, opts: { insecureTls?: boolean }) {
  if (isTauri()) return url
  const insecureTls = !!opts.insecureTls
  try {
    const u = new URL(url)
    if (typeof location !== 'undefined' && u.origin !== location.origin) {
      if (!import.meta.env.DEV && !insecureTls) return url
      const qs = new URLSearchParams()
      qs.set('url', u.toString())
      if (insecureTls) qs.set('insecure', '1')
      return `/__ruf_proxy?${qs.toString()}`
    }
  } catch {
    // ignore
  }
  return url
}

function shouldValidateCertificates(): boolean {
  try {
    return loadAppSettings().validateCertificates
  } catch {
    return true
  }
}

function getCaCertsPem(): string[] {
  try {
    return (loadAppSettings().caCertificates || []).map(c => c.pem).filter(Boolean)
  } catch {
    return []
  }
}

function applyVariables(text: string, vars: Record<string, string>) {
  return text.replaceAll(/\{\{\s*([^}\s]+)\s*\}\}/g, (_m: string, name: string) => resolveVariableValue(name, vars) ?? '')
}

function applyPathParams(url: string, values: Record<string,string>) {
  const hashIdx = url.indexOf('#')
  const beforeHash = hashIdx >= 0 ? url.slice(0, hashIdx) : url
  const hash = hashIdx >= 0 ? url.slice(hashIdx) : ''

  const queryIdx = beforeHash.indexOf('?')
  const beforeQuery = queryIdx >= 0 ? beforeHash.slice(0, queryIdx) : beforeHash
  const query = queryIdx >= 0 ? beforeHash.slice(queryIdx) : ''

  let out = beforeQuery

  out = out.replaceAll(/\/\{([^}]+)\}/g, (m: string, key: string) => {
    const raw = values[key]
    if (raw === undefined) return ''
    if (raw.trim() === '') return ''
    return m
  })

  out = out.replaceAll(/\{([^}]+)\}/g, (_m: string, key: string) => {
    const raw = values[key]
    if (raw === undefined) return ''
    const v = raw.trim()
    if (!v) return ''
    return encodeURIComponent(v)
  })

  const schemeIdx = out.indexOf('://')
  let pathStart = out.length
  if (schemeIdx >= 0) {
    const firstSlashAfterHost = out.indexOf('/', schemeIdx + 3)
    pathStart = firstSlashAfterHost >= 0 ? firstSlashAfterHost : out.length
  } else if (out.startsWith('//')) {
    const firstSlashAfterHost = out.indexOf('/', 2)
    pathStart = firstSlashAfterHost >= 0 ? firstSlashAfterHost : out.length
  } else {
    const firstSlash = out.indexOf('/')
    pathStart = firstSlash >= 0 ? firstSlash : out.length
  }

  if (pathStart < out.length) {
    const prefix = out.slice(0, pathStart)
    let path = out.slice(pathStart)
    path = path.replaceAll(/\/{2,}/g, '/')
    out = prefix + path
  }

  return out + query + hash
}

function getHeader(headers: Record<string, string>, name: string): string | undefined {
  const needle = name.toLowerCase()
  for (const [k, v] of Object.entries(headers)) {
    if (k.toLowerCase() === needle) return v
  }
  return undefined
}

function sanitizeDownloadFileName(name: string): string {
  const trimmed = (name || '').trim()
  if (!trimmed) return 'download'

  let withoutControl = ''
  for (let i = 0; i < trimmed.length; i++) {
    const code = trimmed.charCodeAt(i)
    if (code < 32 || code === 127) continue
    withoutControl += trimmed[i]
  }

  const withoutSlashes = withoutControl.replaceAll(/[\\/]/g, '_')
  const collapsed = withoutSlashes.replaceAll(/\s+/g, ' ').trim()
  return collapsed || 'download'
}

function parseContentDispositionFileName(contentDisposition: string | undefined): string | null {
  const raw = (contentDisposition || '').trim()
  if (!raw) return null

  // RFC 5987: filename*=UTF-8''...
  const filenameStarMatch = /(?:^|;)\s*filename\*\s*=\s*([^;]+)/i.exec(raw)
  if (filenameStarMatch) {
    const v = filenameStarMatch[1].trim().replaceAll(/^"(.*)"$/g, '$1')
    const parts = v.split("''")
    if (parts.length >= 2) {
      const encoded = parts.slice(1).join("''")
      try {
        return decodeURIComponent(encoded)
      } catch {
        return encoded
      }
    }
    return v
  }

  const filenameMatch = /(?:^|;)\s*filename\s*=\s*([^;]+)/i.exec(raw)
  if (filenameMatch) return filenameMatch[1].trim().replaceAll(/^"(.*)"$/g, '$1')
  return null
}

function isTextLikeContentType(contentType: string): boolean {
  const ct = (contentType || '').trim().toLowerCase()
  if (!ct) return true
  if (ct.startsWith('text/')) return true
  if (ct.includes('json')) return true
  if (ct.includes('xml')) return true
  if (ct.includes('yaml') || ct.includes('yml')) return true
  if (ct.includes('csv')) return true
  if (ct.includes('html')) return true
  if (ct.includes('javascript')) return true
  if (ct.includes('x-www-form-urlencoded')) return true
  return false
}

function inferFileExtensionFromContentType(contentType: string): string | null {
  const ct = (contentType || '').trim().toLowerCase()
  if (!ct) return null
  if (ct.includes('pdf')) return '.pdf'
  if (ct.includes('zip')) return '.zip'
  if (ct.includes('gzip')) return '.gz'
  if (ct.includes('json')) return '.json'
  if (ct.includes('csv')) return '.csv'
  if (ct.includes('png')) return '.png'
  if (ct.includes('jpeg') || ct.includes('jpg')) return '.jpg'
  if (ct.includes('gif')) return '.gif'
  if (ct.includes('webp')) return '.webp'
  if (ct.includes('octet-stream')) return '.bin'
  return null
}

function inferFileNameFromUrl(url: string, contentType: string): string {
  try {
    const base = (typeof location !== 'undefined' && location?.href) ? location.href : 'http://localhost/'
    const u = new URL(url, base)
    const parts = u.pathname.split('/').filter(Boolean)
    const last = parts[parts.length - 1] || ''
    const decoded = last ? decodeURIComponent(last) : ''
    if (decoded && decoded !== '/' && decoded !== '.') return decoded
  } catch {
    // ignore
  }

  const ext = inferFileExtensionFromContentType(contentType)
  return ext ? `download${ext}` : 'download'
}

function setHeader(headers: Record<string, string>, name: string, value: string) {
  const needle = name.toLowerCase()
  for (const k of Object.keys(headers)) {
    if (k.toLowerCase() === needle) {
      headers[k] = value
      return
    }
  }
  headers[name] = value
}

function deleteHeader(headers: Record<string, string>, name: string) {
  const needle = name.toLowerCase()
  for (const k of Object.keys(headers)) {
    if (k.toLowerCase() === needle) delete headers[k]
  }
}

export async function runRequest(args: {
  request: RequestItem
  baseUrl: string
  urlTemplateOverride?: string
  variables?: Record<string, string>
  pathParams: Record<string,string>
  queryParams: Record<string,string>
  headers: Record<string,string>
  bodyText?: string
  file?: File | null
  fileFieldName?: string
  files?: Array<{ fieldName: string, file: File }>
  formFields?: Record<string, string>
  signal?: AbortSignal
}): Promise<RunResult> {
  const start = performance.now()
  const vars = args.variables ?? {}
  const validateCertificates = shouldValidateCertificates()

  const baseUrl = (args.baseUrl || '').trim()
  const urlTemplateOverride = (args.urlTemplateOverride || '').trim()
  let url = ''
  if (urlTemplateOverride) {
    if (isAbsoluteUrl(urlTemplateOverride) || urlTemplateOverride.startsWith('//')) {
      url = urlTemplateOverride
    } else if (baseUrl) {
      url = joinUrlParts(baseUrl, urlTemplateOverride)
    } else {
      url = urlTemplateOverride
    }
  } else {
    url = baseUrl
      ? joinUrlParts(baseUrl, args.request.path)
      : args.request.urlTemplate.replace('{{baseUrl}}', '')
  }

  const pathParams = Object.fromEntries(
    Object.entries(args.pathParams).map(([k, v]) => [k, applyVariables(v, vars)]),
  )
  url = applyPathParams(url, pathParams)
  url = applyVariables(url, vars)

  const usp = new URLSearchParams()
  for (const [k,v] of Object.entries(args.queryParams)) {
    const nextV = applyVariables(v, vars)
    if (nextV !== '') usp.set(k, nextV)
  }
  const qs = usp.toString()
  if (qs) url += (url.includes('?') ? '&' : '?') + qs

  const init: RequestInit = {
    method: args.request.method,
    headers: Object.fromEntries(
      Object.entries(args.headers).map(([k, v]) => [k, applyVariables(v, vars)]),
    ),
    signal: args.signal,
  }

  const methodAllowsBody = args.request.method !== 'GET' && args.request.method !== 'HEAD'
  const hasExplicitBodyInput = !!(args.bodyText && args.bodyText.trim()) || !!args.file || !!(args.formFields && Object.keys(args.formFields).length)
  const wantsBody = !!args.request.body || hasExplicitBodyInput

  if (methodAllowsBody && wantsBody) {
    const desiredCt = (getHeader(init.headers as any, 'Content-Type') || args.request.body?.contentType || '').trim()
    const ct = desiredCt.toLowerCase()
    const file = args.file ?? null
    const files = (args.files ?? []).filter(x => x?.file instanceof File)

    const multipartFiles = files.length
      ? files
      : file
        ? [{ fieldName: args.fileFieldName?.trim() || 'file', file }]
        : []

    if (ct.includes('multipart/form-data') && (multipartFiles.length || (args.formFields && Object.keys(args.formFields).length))) {
      const form = new FormData()
      for (const [k, v] of Object.entries(args.formFields ?? {})) form.set(k, applyVariables(v, vars))
      for (const { fieldName, file } of multipartFiles) {
        form.append(fieldName?.trim() || 'file', file)
      }

      const headers = { ...(init.headers as any) } as Record<string, string>
      deleteHeader(headers, 'Content-Type')
      init.headers = headers as any
      init.body = form
    } else if (file) {
      const headers = { ...(init.headers as any) } as Record<string, string>
      if (desiredCt) setHeader(headers, 'Content-Type', desiredCt)
      else if (file.type) setHeader(headers, 'Content-Type', file.type)
      else setHeader(headers, 'Content-Type', 'application/octet-stream')
      init.headers = headers as any
      init.body = file
    } else {
      const headers = { ...(init.headers as any) } as Record<string, string>
      if (desiredCt) setHeader(headers, 'Content-Type', desiredCt)
      init.headers = headers as any
      init.body = applyVariables(args.bodyText ?? '', vars)
    }
  }

  if (typeof init.body === 'string') init.body = applyVariables(init.body, vars)

  const finalUrl = maybeProxyUrl(url, { insecureTls: !validateCertificates })
  const caCertsPem = getCaCertsPem()
  const requestHeadersObj = headersInitToObject(init.headers)
  const requestHeadersBytes = estimateHeadersBytes(init.headers)
  const requestBodyBytes = estimateBodyBytes(init.body)
  const requestBytes = requestHeadersBytes + requestBodyBytes
  let res: Response
  try {
    res = await platformFetch(finalUrl, init, { insecureTls: !validateCertificates, caCertsPem })
  } catch (e: any) {
    const timeMs = Math.round(performance.now() - start)
    if (e?.name === 'AbortError') {
      return {
        ok: false,
        status: 0,
        statusText: 'Canceled',
        timeMs,
        requestHeadersBytes,
        requestBodyBytes,
        requestBytes,
        responseHeadersBytes: 0,
        responseBodyBytes: 0,
        responseBytes: 0,
        requestHeaders: requestHeadersObj,
        responseHeaders: {},
        bodyText: 'Request was canceled.',
      }
    }
    return {
      ok: false,
      status: 0,
      statusText: 'Failed to fetch',
      timeMs,
      requestHeadersBytes,
      requestBodyBytes,
      requestBytes,
      responseHeadersBytes: 0,
      responseBodyBytes: 0,
      responseBytes: 0,
      requestHeaders: requestHeadersObj,
      responseHeaders: {},
      bodyText: e?.message || String(e),
    }
  }
  const timeMs = Math.round(performance.now() - start)

  const headersObj: Record<string,string> = {}
  res.headers.forEach((v,k)=>headersObj[k]=v)

  const responseHeadersBytes = estimateHeadersBytes(headersObj)

  const contentType = getHeader(headersObj, 'Content-Type') || ''
  const contentDisposition = getHeader(headersObj, 'Content-Disposition') || ''
  const fileNameFromDisposition = parseContentDispositionFileName(contentDisposition)
  const isAttachment = /\battachment\b/i.test(contentDisposition) || !!fileNameFromDisposition
  const isTextLike = isTextLikeContentType(contentType)
  const shouldTreatAsFile = isAttachment || (!isTextLike && !!contentType)

  let bodyText = ''
  let file: RunResultFile | undefined
  let responseBodyBytes = 0

  if (shouldTreatAsFile) {
    const inferred = inferFileNameFromUrl(url, contentType)
    const fileName = sanitizeDownloadFileName(fileNameFromDisposition || inferred)

    if (isTextLike) {
      bodyText = await res.text()
      const blob = new Blob([bodyText], { type: contentType || 'text/plain' })
      file = {
        fileName,
        contentType: contentType || blob.type || 'application/octet-stream',
        size: blob.size,
        blob,
        suppressBody: false,
      }
      responseBodyBytes = byteLengthUtf8(bodyText)
    } else {
      const blob = await res.blob()
      file = {
        fileName,
        contentType: blob.type || contentType || 'application/octet-stream',
        size: blob.size,
        blob,
        suppressBody: true,
      }
      bodyText = ''
      responseBodyBytes = blob.size
    }
  } else {
    bodyText = await res.text()
    responseBodyBytes = byteLengthUtf8(bodyText)
  }

  const responseBytes = responseHeadersBytes + responseBodyBytes

  return {
    ok: res.ok,
    status: res.status,
    statusText: res.statusText,
    timeMs,
    requestHeadersBytes,
    requestBodyBytes,
    requestBytes,
    responseHeadersBytes,
    responseBodyBytes,
    responseBytes,
    requestHeaders: requestHeadersObj,
    responseHeaders: headersObj,
    bodyText,
    file,
  }
}

import { useCallback, useEffect, useMemo, useRef, useState } from 'react'
import { createPortal } from 'react-dom'
import { safeJsonParse } from '../../../shared/utils/http'
import { generateJsonSchema } from '../../../shared/utils/jsonSchema'
import type { RequestHistoryItem } from '../../../shared/types/requestHistory'
import type { RunResult } from '../../requestRunner/runRequest'
import { evaluateJsonSearch, type JsonValue } from '../utils/jsonPathSearch'
import { CloseIcon, CopyIcon, SchemaIcon, SearchIcon, TrashIcon } from '../../../shared/icons'
import { copyText } from '../../../shared/utils/clipboard'
import { addResponseSearchHistoryEntry, loadResponseSearchHistory, saveResponseSearchHistory } from '../utils/responseSearchHistory'

type FileSystemWritableFileStreamLike = {
  write: (data: string) => Promise<void>
  close: () => Promise<void>
}

type FileSystemFileHandleLike = {
  createWritable: () => Promise<FileSystemWritableFileStreamLike>
}

function statusClass(status: number) {
  if (status >= 200 && status < 300) return 'status2xx'
  if (status >= 300 && status < 400) return 'status3xx'
  if (status >= 400 && status < 500) return 'status4xx'
  if (status >= 500 && status < 600) return 'status5xx'
  return 'statusOther'
}

function compactStatusText(text: string) {
  const trimmed = (text || '').trim()
  if (!trimmed) return ''
  return trimmed
    .replaceAll(/[^A-Za-z0-9]+/g, ' ')
    .trim()
    .split(/\s+/g)
    .map(w => w.slice(0, 1).toUpperCase() + w.slice(1))
    .join('')
}

function formatBytes(bytes: number) {
  if (!Number.isFinite(bytes) || bytes <= 0) return '0 B'
  if (bytes < 1024) return `${Math.round(bytes)} B`
  if (bytes < 1024 * 1024) return `${(bytes / 1024).toFixed(2)} KB`
  return `${(bytes / (1024 * 1024)).toFixed(2)} MB`
}

function formatDateTime24(ts: number) {
  const d = new Date(ts)
  const dd = String(d.getDate()).padStart(2, '0')
  const mm = String(d.getMonth() + 1).padStart(2, '0')
  const yyyy = String(d.getFullYear()).padStart(4, '0')
  const hh = String(d.getHours()).padStart(2, '0')
  const min = String(d.getMinutes()).padStart(2, '0')
  return `${dd}.${mm}.${yyyy} ${hh}:${min}`
}

function sanitizeForLineCounting(text: string) {
  return (text || '').replaceAll('\r', '')
}

function splitLines(text: string) {
  const sanitized = sanitizeForLineCounting(text)
  const lines = sanitized.split('\n')
  return lines.length ? lines : ['']
}

function getHeaderCaseInsensitive(headers: Record<string, string> | null | undefined, name: string) {
  if (!headers) return undefined
  const needle = name.toLowerCase()
  for (const [k, v] of Object.entries(headers)) {
    if (k.toLowerCase() === needle) return v
  }
  return undefined
}

function looksLikeXml(contentType: string | undefined, bodyText: string) {
  const ct = (contentType || '').toLowerCase()
  if (ct.includes('xml')) return true

  const t = (bodyText || '').trimStart()
  if (!t.startsWith('<')) return false
  if (/^<!doctype\s+html\b/i.test(t)) return false
  if (/^<html\b/i.test(t)) return false
  return true
}

function prettyPrintXml(xmlText: string) {
  const trimmed = (xmlText || '').trim()
  if (!trimmed) return ''

  const parser = new DOMParser()
  const doc = parser.parseFromString(trimmed, 'application/xml')
  if (doc.querySelector('parsererror')) return null

  const serialized = new XMLSerializer().serializeToString(doc)
  const withLines = serialized.replace(/(>)(<)(\/*)/g, '$1\n$2$3')
  const lines = withLines.split('\n')

  let pad = 0
  const indent = (n: number) => '  '.repeat(Math.max(0, n))

  const out: string[] = []
  for (const rawLine of lines) {
    const line = rawLine.trim()
    if (!line) continue

    const isXmlDecl = line.startsWith('<?xml')
    const isClosing = /^<\/[^>]+>/.test(line)
    const isSelfClosing = /^<[^>]+\/>/.test(line) || /^<[^>]+><\/[^>]+>/.test(line)
    const isOpening = /^<[^!?/][^>]*>/.test(line) && !isClosing && !isSelfClosing

    if (isClosing) pad = Math.max(0, pad - 1)
    out.push(`${indent(isXmlDecl ? 0 : pad)}${line}`)
    if (isOpening) pad += 1
  }

  return out.join('\n')
}

export function ResponseViewer(props: {
  result: RunResult | null
  inFlightCount?: number
  tab: 'body' | 'headers' | 'history'
  onTabChange: (tab: 'body' | 'headers' | 'history') => void
  historyItems?: RequestHistoryItem[]
  onSelectHistoryItem?: (item: RequestHistoryItem) => void
  onDeleteHistoryItem?: (item: RequestHistoryItem) => void
}) {
  const [bodyQuery, setBodyQuery] = useState('')
  const [copied, setCopied] = useState(false)
  const [schemaMenuOpen, setSchemaMenuOpen] = useState(false)
  const [schemaCopyFeedback, setSchemaCopyFeedback] = useState(false)
  const [schemaFileBaseName, setSchemaFileBaseName] = useState('requestResponseSchema')
  const schemaMenuWrapRef = useRef<HTMLDivElement | null>(null)
  const saveSchemaDialogRef = useRef<HTMLDialogElement | null>(null)
  const schemaFileNameInputRef = useRef<HTMLInputElement | null>(null)
  const schemaCloseTimerRef = useRef<number | null>(null)
  const [responseSearchOpen, setResponseSearchOpen] = useState(false)
  const [responseSearchCopied, setResponseSearchCopied] = useState(false)
  const responseSearchInputRef = useRef<HTMLInputElement | null>(null)
  const responseSearchHelpDialogRef = useRef<HTMLDialogElement | null>(null)
  const responseSearchHistoryPanelRef = useRef<HTMLDivElement | null>(null)
  const [responseSearchHistory, setResponseSearchHistory] = useState<string[]>(() => loadResponseSearchHistory())
  const [responseSearchHistoryOpen, setResponseSearchHistoryOpen] = useState(false)
  const [responseSearchHistoryAnchor, setResponseSearchHistoryAnchor] = useState<{ left: number, top: number, width: number, placement: 'above' | 'below' } | null>(null)
  const sizePopoverAnchorRef = useRef<HTMLSpanElement | null>(null)
  const sizePopoverCloseTimerRef = useRef<number | null>(null)
  const [sizePopoverOpen, setSizePopoverOpen] = useState(false)
  const [sizePopoverPos, setSizePopoverPos] = useState<{ left: number, top: number } | null>(null)

  const parsed = useMemo(() => {
    if (!props.result) return null
    return safeJsonParse(props.result.bodyText)
  }, [props.result])

  const isJson = props.result ? parsed !== null : false

  const bodyView = useMemo(() => {
    if (!props.result) return { text: '', matchesCount: null as number | null, error: null as string | null }

    if (props.result.file?.suppressBody) {
      const name = props.result.file.fileName || 'download'
      const sizeText = props.result.file.size ? ` (${formatBytes(props.result.file.size)})` : ''
      return { text: `[Binary file received: ${name}${sizeText}]`, matchesCount: null as number | null, error: null as string | null }
    }

    if (!isJson) {
      const ct = getHeaderCaseInsensitive(props.result.responseHeaders, 'Content-Type')
      if (looksLikeXml(ct, props.result.bodyText)) {
        const pretty = prettyPrintXml(props.result.bodyText)
        if (pretty !== null) return { text: pretty, matchesCount: null as number | null, error: null as string | null }
      }
      return { text: props.result.bodyText, matchesCount: null as number | null, error: null as string | null }
    }

    const q = bodyQuery.trim()
    if (!q) return { text: JSON.stringify(parsed, null, 2), matchesCount: null as number | null, error: null as string | null }

    const { matches, error } = evaluateJsonSearch(parsed as JsonValue, q)
    if (error) return { text: '', matchesCount: matches.length, error }
    if (!matches.length) return { text: '', matchesCount: 0, error: null as string | null }

    const out = Array.isArray(parsed) ? matches : (matches.length === 1 ? matches[0] : matches)
    return { text: JSON.stringify(out, null, 2), matchesCount: matches.length, error: null as string | null }
  }, [bodyQuery, isJson, parsed, props.result])

  const result = props.result
  const tab = props.tab
  const requestHeadersText = result ? JSON.stringify(result.requestHeaders ?? {}, null, 2) : ''
  const responseHeadersText = result ? JSON.stringify(result.responseHeaders ?? {}, null, 2) : ''
  const headersCopyPayload = result
    ? JSON.stringify({ requestHeaders: result.requestHeaders ?? {}, responseHeaders: result.responseHeaders ?? {} }, null, 2)
    : ''
  const historyItems = props.historyItems ?? []
  const copyPayload = tab === 'body' ? bodyView.text : headersCopyPayload
  const canCopy = !!result && copyPayload.length > 0
  const canGenerateSchema = tab === 'body' && isJson
  const responseSearchErrorText = tab === 'body' && responseSearchOpen && isJson && !!bodyQuery.trim() ? bodyView.error : null
  const responseSearchMatchesCount = !bodyView.error && bodyQuery.trim() && typeof bodyView.matchesCount === 'number' ? bodyView.matchesCount : null
  const responseSearchHasMatchesMeta = tab === 'body' && responseSearchOpen && isJson && typeof responseSearchMatchesCount === 'number'

  const onDownloadFile = useCallback(async () => {
    const f = result?.file
    if (!f) return

    const suggestedName = f.fileName || 'download'

    const savePickerFn = (window as any)?.showSaveFilePicker as undefined | ((opts?: any) => Promise<any>)
    if (typeof savePickerFn === 'function') {
      try {
        const handle = await savePickerFn({ suggestedName })
        const writable = await handle.createWritable()
        await writable.write(f.blob)
        await writable.close()
        return
      } catch (e: any) {
        if (e?.name === 'AbortError') return
      }
    }

    const url = URL.createObjectURL(f.blob)
    const a = document.createElement('a')
    a.href = url
    a.download = suggestedName
    a.style.display = 'none'
    document.body.appendChild(a)
    a.click()
    a.remove()
    setTimeout(() => URL.revokeObjectURL(url), 1000)
  }, [result])

  const bodyLines = useMemo(() => splitLines(bodyView.text), [bodyView.text])
  const bodyLineCount = bodyLines.length
  const bodyGutterWidthCh = Math.max(2, String(bodyLineCount).length) + 1

  const requestHeadersLines = useMemo(() => splitLines(requestHeadersText), [requestHeadersText])
  const requestHeadersLineCount = requestHeadersLines.length
  const requestHeadersGutterWidthCh = Math.max(2, String(requestHeadersLineCount).length) + 1

  const responseHeadersLines = useMemo(() => splitLines(responseHeadersText), [responseHeadersText])
  const responseHeadersLineCount = responseHeadersLines.length
  const responseHeadersGutterWidthCh = Math.max(2, String(responseHeadersLineCount).length) + 1

  async function onCopy() {
    await copyText(copyPayload)
    setCopied(true)
    setTimeout(() => setCopied(false), 900)
  }

  async function onCopyResponseSearch() {
    const q = bodyQuery.trim()
    if (!q) return
    await copyText(q)
    setResponseSearchCopied(true)
    setTimeout(() => setResponseSearchCopied(false), 800)
  }

  function recordResponseSearchHistory(query: string) {
    setResponseSearchHistory(prev => {
      const next = addResponseSearchHistoryEntry(prev, query, 10)
      if (next === prev) return prev
      saveResponseSearchHistory(next)
      return next
    })
  }

  function deleteResponseSearchHistoryItem(queryRaw: string) {
    const q = queryRaw.trim()
    if (!q) return
    setResponseSearchHistory(prev => {
      const next = prev.filter(v => v !== q)
      if (next.length === prev.length) return prev
      saveResponseSearchHistory(next)
      return next
    })
  }

  function clearResponseSearchHistory() {
    setResponseSearchHistory([])
    saveResponseSearchHistory([])
  }

  function closeResponseSearchHistoryMenu() {
    setResponseSearchHistoryOpen(false)
    setResponseSearchHistoryAnchor(null)
  }

  function toggleResponseSearchHistoryMenu(anchorEl: HTMLElement) {
    if (responseSearchHistoryOpen) {
      closeResponseSearchHistoryMenu()
      return
    }

    const rect = anchorEl.getBoundingClientRect()
    const margin = 8
    const assumedMaxHeight = 240

    let width = rect.width
    if (width < 220) width = 220
    if (width > 520) width = 520

    let left = rect.left
    const aboveBottom = rect.top - 6
    const canPlaceAbove = aboveBottom - assumedMaxHeight >= margin
    const placement: 'above' | 'below' = canPlaceAbove ? 'above' : 'below'
    const top = placement === 'above' ? aboveBottom : (rect.bottom + 6)

    if (left + width > window.innerWidth - margin) left = Math.max(margin, window.innerWidth - margin - width)
    if (left < margin) left = margin

    setResponseSearchHistoryOpen(true)
    setResponseSearchHistoryAnchor({ left, top, width, placement })
  }

  const clearSchemaCloseTimer = useCallback(() => {
    if (schemaCloseTimerRef.current === null) return
    window.clearTimeout(schemaCloseTimerRef.current)
    schemaCloseTimerRef.current = null
  }, [])

  const closeSchemaMenu = useCallback(() => {
    clearSchemaCloseTimer()
    setSchemaCopyFeedback(false)
    setSchemaMenuOpen(false)
  }, [clearSchemaCloseTimer])

  useEffect(() => {
    if (!schemaMenuOpen) return

    function onPointerDown(e: PointerEvent) {
      const t = e.target as Node | null
      const wrap = schemaMenuWrapRef.current
      if (t && wrap && wrap.contains(t)) return
      closeSchemaMenu()
    }

    function onKeyDown(e: KeyboardEvent) {
      if (e.key === 'Escape') closeSchemaMenu()
    }

    window.addEventListener('pointerdown', onPointerDown)
    window.addEventListener('keydown', onKeyDown)
    return () => {
      window.removeEventListener('pointerdown', onPointerDown)
      window.removeEventListener('keydown', onKeyDown)
    }
  }, [closeSchemaMenu, schemaMenuOpen])

  function getSchemaText() {
    if (!isJson) return null
    const schema = generateJsonSchema(parsed)
    return JSON.stringify(schema, null, 2)
  }

  async function copySchemaToClipboard() {
    const schemaText = getSchemaText()
    if (!schemaText) return
    await copyText(schemaText)
    setSchemaCopyFeedback(true)
    clearSchemaCloseTimer()
    schemaCloseTimerRef.current = window.setTimeout(() => {
      closeSchemaMenu()
    }, 900)
  }

  function openSaveSchemaDialog() {
    closeSchemaMenu()
    setSchemaFileBaseName('requestResponseSchema')
    saveSchemaDialogRef.current?.showModal()
    setTimeout(() => schemaFileNameInputRef.current?.focus(), 0)
  }

  function normalizeSchemaFileName(base: string) {
    const trimmed = base.trim() || 'requestResponseSchema'
    return trimmed.toLowerCase().endsWith('.json') ? trimmed : `${trimmed}.json`
  }

  async function saveSchemaWithName(baseName: string) {
    const schemaText = getSchemaText()
    if (!schemaText) return

    const fileName = normalizeSchemaFileName(baseName)

    try {
      const w = window as unknown as { showSaveFilePicker?: (options: unknown) => Promise<FileSystemFileHandleLike> }
      if (typeof w.showSaveFilePicker === 'function') {
        const handle = await w.showSaveFilePicker({
