  const inFlightCount = props.inFlightCount ?? 0
  const statusLine = inFlightCount > 0 ? 'Sending...' : 'Run a request to see the response.'

  useEffect(() => {
    if (tab === 'body') return
    setResponseSearchOpen(false)
    closeResponseSearchHistoryMenu()
