import { useEffect, useMemo, useRef, useState } from 'react'
import type { Collection } from '../../collectionTree'
import type { Environment, GlobalSqlConnectionItem } from '../../../shared/types/environment'
import { resolveVariableValue } from '../../../shared/utils/variables'
import { DB_ENV_KEYS, buildDbConnectionString, getDbConnectionStringPreview, getDbFormStateFromEnv, hasDbConfigInEnv, runDbSql } from '../../environment'

type DbConnOption = {
  id: string
  label: string
  type: 'postgres' | 'mysql'
  connectionString: string
  connectionPreview: string
  variables: Record<string, string>
}

type OutputEntry = { kind: 'sys' | 'out' | 'err' | 'in'; text: string }

const SQL_TERMINAL_HEIGHT_KEY = 'ruf_sql_terminal_height_v1'
const SQL_TERMINAL_SELECTED_CONN_KEY = 'ruf_sql_terminal_selected_conn_v1'
const SQL_TERMINAL_SQL_KEY = 'ruf_sql_terminal_sql_v1'
const SQL_TERMINAL_SPLIT_KEY = 'ruf_sql_terminal_split_v1'
const SQL_TERMINAL_SCHEMA_KEY = 'ruf_sql_terminal_schema_v1'

function safeLoadNumber(key: string): number | null {
  try {
    const raw = localStorage.getItem(key)
    if (!raw) return null
    const n = Number(raw)
    return Number.isFinite(n) && n > 0 ? n : null
  } catch {
    return null
  }
}

function safeLoadString(key: string): string | null {
  try {
    const raw = localStorage.getItem(key)
    return typeof raw === 'string' ? raw : null
  } catch {
    return null
  }
}

function safeLoadFraction(key: string): number | null {
  try {
    const raw = localStorage.getItem(key)
    if (!raw) return null
    const n = Number(raw)
    if (!Number.isFinite(n)) return null
    if (n <= 0 || n >= 1) return null
    return n
  } catch {
    return null
  }
}

function safeSave(key: string, value: string) {
  try {
    localStorage.setItem(key, value)
  } catch {
    // ignore
  }
}

function safeRemove(key: string) {
  try {
    localStorage.removeItem(key)
  } catch {
    // ignore
  }
}

function applyVariables(text: string, vars: Record<string, string>) {
  return text.replaceAll(/\{\{\s*([^}\s]+)\s*\}\}/g, (_m: string, name: string) => resolveVariableValue(name, vars) ?? '')
}

function quoteIdentPostgres(name: string) {
  return `"${name.replaceAll('"', '""')}"`
}

function quoteSqlStringLiteral(value: string) {
  return `'${value.replaceAll("'", "''")}'`
}

function looksLikeSelectOrWith(sql: string) {
  const s = sql.trimStart()
  return /^select\b/i.test(s) || /^with\b/i.test(s)
}

function makeTableAlias(tableName: string): string {
  const raw = (tableName || '').replaceAll('"', '').trim()
  if (!raw) return 't'

  // Split by common separators and also by camelCase boundaries.
  const parts = raw
    .replaceAll(/([a-z0-9])([A-Z])/g, '$1 $2')
    .split(/[^a-zA-Z0-9]+/g)
    .filter(Boolean)

  const letters = parts.map(p => p[0] ?? '').filter(Boolean)
  const alias = letters.join('').slice(0, 6).toLowerCase()
  return alias || raw.slice(0, 1).toLowerCase() || 't'
}

function stripQuotes(ident: string) {
  return (ident || '').replaceAll('"', '').trim()
}

function parseFromAndJoinAliases(sql: string): Record<string, string> {
  const out: Record<string, string> = {}
  const re = /\b(from|join)\s+([a-zA-Z0-9_".]+)\s*(?:as\s+)?([a-zA-Z0-9_"]+)?/gi
  let m: RegExpExecArray | null
  while ((m = re.exec(sql)) !== null) {
    const tableRef = (m[2] ?? '').trim()
    if (!tableRef || tableRef.startsWith('(')) continue
    const aliasRaw = (m[3] ?? '').trim()
    const tableName = stripQuotes(tableRef.split('.').pop() ?? tableRef)
    if (!tableName) continue
    const alias = stripQuotes(aliasRaw)
    if (alias && !/^(on|where|group|order|limit|inner|left|right|full|cross|join)$/i.test(alias)) out[alias] = tableName
    // Also allow referencing by the table name itself.
    out[tableName] = tableName
  }
  return out
}

function clampHistory<T>(arr: T[], max: number): T[] {
  if (arr.length <= max) return arr
  return arr.slice(arr.length - max)
}

function formatTime(d: Date) {
  const pad2 = (n: number) => String(n).padStart(2, '0')
  return `${pad2(d.getHours())}:${pad2(d.getMinutes())}:${pad2(d.getSeconds())}`
}

function buildDbConnOptions(
  collections: Collection[],
  envByCollection: Record<string, Environment>,
  extraConnections: GlobalSqlConnectionItem[] | undefined,
): DbConnOption[] {
  const byId = new Map(collections.map(c => [c.id, c]))
  const out: DbConnOption[] = []
  const appSignatures = new Set<string>()

  for (const conn of extraConnections ?? []) {
    if (!conn) continue
    const connectionString = buildDbConnectionString(conn)
    if (!connectionString) continue
    appSignatures.add(`${conn.type}|${connectionString}`)
  }

  for (const [collectionId, env] of Object.entries(envByCollection)) {
    if (!env) continue
    if (!hasDbConfigInEnv(env)) continue

    const collection = byId.get(collectionId)
    if (!collection) continue

    const rawType = env.variables?.[DB_ENV_KEYS.type]
    const type = rawType === 'mysql' ? 'mysql' : 'postgres'
    const fromEnv = (env.variables?.[DB_ENV_KEYS.connectionString] ?? '').trim()
    const connectionString = fromEnv || buildDbConnectionString(getDbFormStateFromEnv(env))
    if (!connectionString) continue
    if (appSignatures.has(`${type}|${connectionString}`)) continue

    const connectionPreview = getDbConnectionStringPreview(connectionString, false)
    out.push({
      id: collectionId,
      label: collection.name || collectionId,
      type,
      connectionString,
      connectionPreview,
      variables: env.variables ?? {},
    })
  }

  for (const conn of (extraConnections ?? []).slice(0, 1)) {
    if (!conn) continue
    const connectionString = buildDbConnectionString(conn)
    if (!connectionString) continue
    out.push({
      id: `app:${conn.id}`,
      label: 'App',
      type: conn.type,
      connectionString,
      connectionPreview: getDbConnectionStringPreview(connectionString, false),
      variables: {},
    })
  }

  return out.sort((a, b) => a.label.localeCompare(b.label))
}

export function SqlTerminalDrawer(props: {
  open: boolean
  onClose: () => void
  collections: Collection[]
  environmentsByCollection: Record<string, Environment>
  extraConnections?: GlobalSqlConnectionItem[]
}) {
  const { open, onClose } = props

  const [busy, setBusy] = useState(false)
  const [menuOpen, setMenuOpen] = useState(false)
  const [schemaMenuOpen, setSchemaMenuOpen] = useState(false)
  const [heightPx, setHeightPx] = useState<number | null>(() => safeLoadNumber(SQL_TERMINAL_HEIGHT_KEY))
  const [selectedConnId, setSelectedConnId] = useState<string | null>(() => safeLoadString(SQL_TERMINAL_SELECTED_CONN_KEY))
  const [sql, setSql] = useState(() => safeLoadString(SQL_TERMINAL_SQL_KEY) ?? '')
  const [output, setOutput] = useState<OutputEntry[]>([])
  const [resultRows, setResultRows] = useState<Array<Record<string, unknown>> | null>(null)
  const [resultColumns, setResultColumns] = useState<string[] | null>(null)
  const [resultHint, setResultHint] = useState<string | null>(null)
  const [splitLeftFraction, setSplitLeftFraction] = useState<number>(() => safeLoadFraction(SQL_TERMINAL_SPLIT_KEY) ?? 0.42)
  const [schemas, setSchemas] = useState<string[]>([])
  const [selectedSchema, setSelectedSchema] = useState<string>(() => safeLoadString(SQL_TERMINAL_SCHEMA_KEY) ?? '')
  const [tables, setTables] = useState<string[]>([])
  const [columnsByTableKey, setColumnsByTableKey] = useState<Record<string, string[]>>({})
  const [cursorPos, setCursorPos] = useState<number>(0)
  const [tableSuggestOpen, setTableSuggestOpen] = useState(false)
  const [suggestMode, setSuggestMode] = useState<'table' | 'column'>('table')
  const [tableSuggestKind, setTableSuggestKind] = useState<'from' | 'into'>('from')
  const [columnTargetTableKey, setColumnTargetTableKey] = useState<string | null>(null)
  const [columnLoading, setColumnLoading] = useState(false)
  const [tableSuggestPrefix, setTableSuggestPrefix] = useState<string>('')
  const [tableSuggestReplaceRange, setTableSuggestReplaceRange] = useState<{ start: number; end: number } | null>(null)

  const menuWrapRef = useRef<HTMLDivElement | null>(null)
  const schemaMenuWrapRef = useRef<HTMLDivElement | null>(null)
  const sqlRef = useRef<HTMLTextAreaElement | null>(null)
  const outputRef = useRef<HTMLDivElement | null>(null)
  const bodyRef = useRef<HTMLDivElement | null>(null)
  const runRef = useRef<(() => void) | null>(null)
  const sectionRef = useRef<HTMLElement | null>(null)
  const pendingCaretRef = useRef<number | null>(null)
  const editHistoryRef = useRef<{ stack: Array<{ text: string; caret: number }>; index: number; applying: boolean }>({
    stack: [{ text: safeLoadString(SQL_TERMINAL_SQL_KEY) ?? '', caret: 0 }],
    index: 0,
    applying: false,
  })

  const connOptions = useMemo(
    () => buildDbConnOptions(props.collections, props.environmentsByCollection, props.extraConnections),
    [props.collections, props.environmentsByCollection, props.extraConnections],
  )
  const selectedConn = useMemo(() => connOptions.find(c => c.id === selectedConnId) ?? null, [connOptions, selectedConnId])

  useEffect(() => {
    if (!open) return
    requestAnimationFrame(() => sqlRef.current?.focus())
  }, [open])

  useEffect(() => {
    runRef.current = () => void run()
  })

  useEffect(() => {
    const pending = pendingCaretRef.current
    if (pending == null) return
    pendingCaretRef.current = null
    const ta = sqlRef.current
    if (!ta) return
    ta.focus()
    ta.selectionStart = pending
    ta.selectionEnd = pending
    setCursorPos(pending)
  }, [sql])

  useEffect(() => {
    if (!open) return
    function onKeyDown(e: KeyboardEvent) {
      if (e.key === 'Escape') onClose()
    }
    window.addEventListener('keydown', onKeyDown)
    return () => window.removeEventListener('keydown', onKeyDown)
  }, [open, onClose])

  useEffect(() => {
    if (!menuOpen) return

    function onPointerDown(e: PointerEvent) {
      const t = e.target as Node | null
      const wrap = menuWrapRef.current
      if (t && wrap && wrap.contains(t)) return
      setMenuOpen(false)
    }

    function onKeyDown(e: KeyboardEvent) {
      if (e.key === 'Escape') setMenuOpen(false)
    }

    window.addEventListener('pointerdown', onPointerDown)
    window.addEventListener('keydown', onKeyDown)
    return () => {
      window.removeEventListener('pointerdown', onPointerDown)
      window.removeEventListener('keydown', onKeyDown)
    }
  }, [menuOpen])

  useEffect(() => {
    if (!schemaMenuOpen) return

    function onPointerDown(e: PointerEvent) {
      const t = e.target as Node | null
      const wrap = schemaMenuWrapRef.current
      if (t && wrap && wrap.contains(t)) return
      setSchemaMenuOpen(false)
    }

    function onKeyDown(e: KeyboardEvent) {
      if (e.key === 'Escape') setSchemaMenuOpen(false)
    }

    window.addEventListener('pointerdown', onPointerDown)
    window.addEventListener('keydown', onKeyDown)
    return () => {
      window.removeEventListener('pointerdown', onPointerDown)
      window.removeEventListener('keydown', onKeyDown)
    }
  }, [schemaMenuOpen])

  useEffect(() => {
    if (heightPx == null) return
    safeSave(SQL_TERMINAL_HEIGHT_KEY, String(heightPx))
  }, [heightPx])

  useEffect(() => {
    if (!selectedConnId) safeRemove(SQL_TERMINAL_SELECTED_CONN_KEY)
    else safeSave(SQL_TERMINAL_SELECTED_CONN_KEY, selectedConnId)
  }, [selectedConnId])

  useEffect(() => {
    safeSave(SQL_TERMINAL_SQL_KEY, sql)
  }, [sql])

  useEffect(() => {
    safeSave(SQL_TERMINAL_SPLIT_KEY, String(splitLeftFraction))
  }, [splitLeftFraction])

  useEffect(() => {
    if (!selectedSchema) safeRemove(SQL_TERMINAL_SCHEMA_KEY)
    else safeSave(SQL_TERMINAL_SCHEMA_KEY, selectedSchema)
  }, [selectedSchema])

  useEffect(() => {
    const el = outputRef.current
    if (!el) return
    el.scrollTop = el.scrollHeight
  }, [output.length, open])

  useEffect(() => {
    if (!connOptions.length) return
    setSelectedConnId(prev => {
      if (prev && connOptions.some(c => c.id === prev)) return prev
      const fromStorage = safeLoadString(SQL_TERMINAL_SELECTED_CONN_KEY)
      if (fromStorage && connOptions.some(c => c.id === fromStorage)) return fromStorage
      return connOptions[0]?.id ?? null
    })
  }, [connOptions])

  async function loadSchemas(conn: DbConnOption) {
    if (conn.type !== 'postgres') {
      setSchemas([])
      setSelectedSchema('')
      return
    }
    try {
      const r = await runDbSql({
        type: conn.type,
        connectionString: conn.connectionString,
        sql: "select schema_name as name from information_schema.schemata where schema_name <> 'information_schema' and schema_name not like 'pg\\_%' escape '\\' order by case when schema_name='public' then 0 else 1 end, schema_name",
        timeoutMs: 15_000,
      })
      const rows = r.ok ? (r.rows ?? null) : null
      const names = rows
        ? rows
            .map(x => (x && typeof x === 'object' && 'name' in x ? String((x as Record<string, unknown>).name ?? '') : ''))
            .filter(Boolean)
        : []
      setSchemas(names)
      setSelectedSchema(prev => {
        const stored = safeLoadString(SQL_TERMINAL_SCHEMA_KEY) ?? ''
        const candidate = prev || stored
        if (candidate && names.includes(candidate)) return candidate
        if (names.includes('public')) return 'public'
        return names[0] ?? ''
      })
    } catch {
      setSchemas([])
      setSelectedSchema('')
    }
  }

  async function loadTables(conn: DbConnOption, schema: string) {
    if (conn.type !== 'postgres') {
      setTables([])
      return
    }
    if (!schema) {
      setTables([])
      return
    }
    try {
      const sql = `select table_name as name from information_schema.tables where table_schema = ${quoteSqlStringLiteral(schema)} and table_type in ('BASE TABLE','VIEW') order by table_name`
      const r = await runDbSql({
        type: conn.type,
        connectionString: conn.connectionString,
        sql,
        timeoutMs: 15_000,
      })
      const rows = r.ok ? (r.rows ?? null) : null
      const names = rows
        ? rows
            .map(x => (x && typeof x === 'object' && 'name' in x ? String((x as Record<string, unknown>).name ?? '') : ''))
            .filter(Boolean)
        : []
      setTables(names)
    } catch {
      setTables([])
    }
  }

  useEffect(() => {
    if (!open) return
    if (!selectedConn) return
    void loadSchemas(selectedConn)
    setTables([])
    setColumnsByTableKey({})
  }, [open, selectedConnId])

  useEffect(() => {
    if (!open) return
    if (!selectedConn) return
    if (selectedConn.type !== 'postgres') return
    void loadTables(selectedConn, selectedSchema)
  }, [open, selectedConnId, selectedSchema])

  async function loadColumnsForTable(conn: DbConnOption, schema: string, tableName: string) {
    if (conn.type !== 'postgres') return
    if (!schema || !tableName) return
    const key = `${schema}.${tableName}`
    if (columnsByTableKey[key]) return

    setColumnLoading(true)
    try {
      const sql = `select column_name as name from information_schema.columns where table_schema = ${quoteSqlStringLiteral(schema)} and table_name = ${quoteSqlStringLiteral(tableName)} order by ordinal_position`
      const r = await runDbSql({ type: conn.type, connectionString: conn.connectionString, sql, timeoutMs: 15_000 })
      const rows = r.ok ? (r.rows ?? null) : null
      const names = rows
        ? rows
            .map(x => (x && typeof x === 'object' && 'name' in x ? String((x as Record<string, unknown>).name ?? '') : ''))
            .filter(Boolean)
        : []
      setColumnsByTableKey(prev => ({ ...prev, [key]: names }))
    } finally {
      setColumnLoading(false)
    }
  }

  function onResizeHandlePointerDown(e: React.PointerEvent<HTMLDivElement>) {
    if (!open) return
    const startY = e.clientY
    const startHeight = heightPx ?? Math.round(Math.min(window.innerHeight * 0.38, 420))

    const min = 240
    const max = Math.max(min, Math.round(window.innerHeight * 0.85))

    function clamp(n: number) {
      return Math.max(min, Math.min(max, n))
    }

    function onMove(ev: PointerEvent) {
      const dy = ev.clientY - startY
      const next = clamp(Math.round(startHeight - dy))
      setHeightPx(next)
    }

    function onUp() {
      window.removeEventListener('pointermove', onMove)
      window.removeEventListener('pointerup', onUp)
    }

    window.addEventListener('pointermove', onMove)
    window.addEventListener('pointerup', onUp, { once: true })
  }

  function pushOutput(add: OutputEntry[]) {
    if (!add.length) return
    setOutput(prev => [...prev, ...add])
  }

  function onSplitHandlePointerDown(e: React.PointerEvent<HTMLDivElement>) {
    if (!open) return
    const wrap = bodyRef.current
    if (!wrap) return

    const rect = wrap.getBoundingClientRect()
    const startX = e.clientX
    const startFrac = splitLeftFraction

    const minLeftPx = 260
    const minRightPx = 320
    const maxFracFromLeft = Math.max(0.1, Math.min(0.9, (rect.width - minRightPx) / rect.width))
    const minFracFromLeft = Math.max(0.1, Math.min(0.9, minLeftPx / rect.width))

    function clampFrac(n: number) {
      return Math.max(minFracFromLeft, Math.min(maxFracFromLeft, n))
    }

    function onMove(ev: PointerEvent) {
      const dx = ev.clientX - startX
      const next = clampFrac(startFrac + dx / rect.width)
      setSplitLeftFraction(next)
    }

    function onUp() {
      window.removeEventListener('pointermove', onMove)
      window.removeEventListener('pointerup', onUp)
    }

    window.addEventListener('pointermove', onMove)
    window.addEventListener('pointerup', onUp, { once: true })
  }

  const effectiveResultColumns = useMemo(() => {
    if (resultColumns?.length) return resultColumns
    const rows = resultRows
    if (!rows || !rows.length) return []
    const first = rows[0] ?? {}
    return Object.keys(first)
  }, [resultColumns, resultRows])

  const tableSuggestions = useMemo(() => {
    const p = (tableSuggestPrefix || '').toLowerCase()
    if (!p) return tables.slice(0, 80)
    return tables.filter(t => t.toLowerCase().includes(p)).slice(0, 80)
  }, [tables, tableSuggestPrefix])

  const columnSuggestions = useMemo(() => {
    const key = columnTargetTableKey
    if (!key) return []
    const cols = columnsByTableKey[key] ?? []
    const p = (tableSuggestPrefix || '').toLowerCase()
    if (!p) return cols.slice(0, 120)
    return cols.filter(c => c.toLowerCase().includes(p)).slice(0, 120)
  }, [columnsByTableKey, columnTargetTableKey, tableSuggestPrefix])

  useEffect(() => {
    if (!open) return
    const ta = sqlRef.current
    if (!ta) return

    const pos = cursorPos
    const before = sql.slice(0, pos)

    // Column suggestion: <alias_or_table>.<prefix>
    const colMatch = before.match(/(?:^|[^a-zA-Z0-9_"])([a-zA-Z0-9_"]+)\.([a-zA-Z0-9_"]*)$/i)
    if (colMatch) {
      const token = stripQuotes(colMatch[1] ?? '')
      const colPrefix = stripQuotes(colMatch[2] ?? '')
      const aliases = parseFromAndJoinAliases(sql)
      const tableName = aliases[token]
      if (tableName && selectedConn?.type === 'postgres' && selectedSchema) {
        const key = `${selectedSchema}.${tableName}`
        setSuggestMode('column')
        setColumnTargetTableKey(key)
        setTableSuggestPrefix(colPrefix)
        setTableSuggestReplaceRange({ start: pos - (colMatch[2] ?? '').length, end: pos })
        void loadColumnsForTable(selectedConn, selectedSchema, tableName)
        setTableSuggestOpen(true)
        return
      }
    }

    // Table suggestion: FROM/INTO ...<prefix>
    const tableMatch = before.match(/(?:^|[\s(])(from|into)(?:\s+([a-zA-Z0-9_".]*))?$/i)
    if (!tableMatch || !tables.length) {
      setTableSuggestOpen(false)
      setTableSuggestReplaceRange(null)
      setTableSuggestPrefix('')
      setColumnTargetTableKey(null)
      return
    }

    const kind = (tableMatch[1] || 'from').toLowerCase() === 'into' ? 'into' : 'from'
    const prefix = tableMatch[2] ?? ''
    const start = pos - prefix.length
    const end = pos
    setSuggestMode('table')
    setTableSuggestKind(kind)
    setTableSuggestPrefix(prefix.replaceAll('"', ''))
    setTableSuggestReplaceRange({ start, end })
    setColumnTargetTableKey(null)
    setTableSuggestOpen(true)
  }, [open, sql, cursorPos, tables.length, selectedConnId, selectedSchema])

  async function run() {
    if (busy) return
    const conn = selectedConn
    if (!conn) {
      pushOutput([{ kind: 'err', text: 'No database connection selected. Configure DB in Environment settings.' }])
      return
    }

    const raw = sql.trim()
    if (!raw) {
      pushOutput([{ kind: 'sys', text: 'Nothing to run.' }])
      return
    }

    const startedAt = new Date()
    pushOutput([{ kind: 'in', text: `-- ${formatTime(startedAt)} ${conn.label} (${conn.type})` }])
    setResultRows(null)
    setResultColumns(null)
    setResultHint(null)

    setBusy(true)
    try {
      const renderedSql = applyVariables(raw, conn.variables)
      const sqlToRun =
        conn.type === 'postgres' && selectedSchema
          ? (looksLikeSelectOrWith(renderedSql)
              ? (renderedSql.trimStart().toLowerCase().startsWith('with')
                  ? renderedSql.replace(
                      /^\s*with\b/i,
                      m => `${m} __ruf_search_path as (select set_config('search_path', ${quoteSqlStringLiteral(selectedSchema)}, true)),`,
                    )
                  : `with __ruf_search_path as (select set_config('search_path', ${quoteSqlStringLiteral(selectedSchema)}, true))\n${renderedSql}`)
              : `set search_path to ${quoteIdentPostgres(selectedSchema)};\n${renderedSql}`)
          : renderedSql
      const r = await runDbSql({ type: conn.type, connectionString: conn.connectionString, sql: sqlToRun, timeoutMs: 30_000 })
      const prefix = r.ok ? 'OK' : 'ERROR'
      pushOutput([{ kind: r.ok ? 'out' : 'err', text: `${prefix}: ${r.message || ''} (${r.durationMs}ms)` }])
      const rows = r.rows ?? null
      if (r.ok && Array.isArray(r.columns) && r.columns.length) {
        setResultColumns(r.columns)
      }

      if (r.ok && Array.isArray(rows)) {
        if (rows.length && typeof rows[0] === 'object' && rows[0] != null && !Array.isArray(rows[0])) {
          setResultRows(rows as Array<Record<string, unknown>>)
          setResultHint(`${rows.length} row(s)`)
        } else if (!rows.length && (r.columns?.length ?? 0) > 0) {
          setResultRows([])
          setResultHint('0 row(s)')
        } else if (!rows.length) {
          setResultHint('0 row(s)')
        }
      } else if (r.ok && typeof r.rowsAffected === 'number') {
        setResultHint(`${r.rowsAffected} affected`)
      }
    } catch (e: unknown) {
      pushOutput([{ kind: 'err', text: e instanceof Error ? e.message : String(e) }])
    } finally {
      setBusy(false)
      requestAnimationFrame(() => sqlRef.current?.focus())
    }
  }

  const selectedLabel = selectedConn ? `${selectedConn.label}: ${selectedConn.connectionPreview}` : (connOptions.length ? 'Select DB…' : 'No DB connections')

  useEffect(() => {
    if (!open) return

    function onGlobalKeyDown(e: KeyboardEvent) {
      if (!(e.ctrlKey || e.metaKey) || e.key !== 'Enter') return
      const section = sectionRef.current
      const active = document.activeElement
      if (section && active && !section.contains(active)) return
      e.preventDefault()
      e.stopPropagation()
      runRef.current?.()
    }

    window.addEventListener('keydown', onGlobalKeyDown, true)
    return () => window.removeEventListener('keydown', onGlobalKeyDown, true)
  }, [open])

  return (
    <>
      <div className={open ? 'terminalBackdrop terminalBackdropOpen' : 'terminalBackdrop'} onClick={onClose} />
      <section
        ref={sectionRef}
        className={open ? 'terminalDrawer terminalDrawerOpen sqlTerminalDrawer' : 'terminalDrawer sqlTerminalDrawer'}
        aria-hidden={!open}
        style={heightPx != null ? { height: `${heightPx}px` } : undefined}
      >
        <div className="terminalResizeHandle" onPointerDown={onResizeHandlePointerDown} />

        <header className="terminalHeader">
          <div className="terminalTitle mono" style={{ flex: '1 1 auto', minWidth: 0 }}>
            SQL
            <div ref={menuOpen ? menuWrapRef : null} className="selectMenuWrap sqlTerminalConnMenu">
              <button
                type="button"
                className="selectMenuBtn mono"
                onPointerDown={e => e.stopPropagation()}
                onClick={e => {
                  e.preventDefault()
                  e.stopPropagation()
                  if (!connOptions.length) return
                  setMenuOpen(v => !v)
                }}
                aria-haspopup="menu"
                aria-expanded={menuOpen}
                aria-label="Database connection"
                title={selectedConn?.connectionPreview ?? 'Database connection'}
              >
                {selectedLabel}
              </button>

              {menuOpen ? (
                <div
                  className="selectMenuPanel"
                  role="menu"
                  onPointerDown={e => {
                    e.preventDefault()
                    e.stopPropagation()
                  }}
                  onClick={e => {
                    e.preventDefault()
                    e.stopPropagation()
                  }}
                >
                  {connOptions.map(o => (
                    <button
                      key={o.id}
                      type="button"
                      className={`selectMenuItem ${selectedConnId === o.id ? 'selectMenuItemActive' : ''}`}
                      role="menuitem"
                      title={o.connectionPreview}
                      onClick={() => {
                        setMenuOpen(false)
                        setSelectedConnId(o.id)
                        requestAnimationFrame(() => sqlRef.current?.focus())
                      }}
                    >
                      <span className="mono">{o.label}</span>
                      <span style={{ opacity: 0.75 }}>{` — ${o.connectionPreview}`}</span>
                    </button>
                  ))}
                </div>
              ) : null}
            </div>
          </div>

          <div className="terminalHeaderActions">
            <button
              type="button"
              className="iconBtn"
              onClick={() => {
                setOutput([])
                setResultRows(null)
                setResultColumns(null)
                setResultHint(null)
                setSql('')
                requestAnimationFrame(() => sqlRef.current?.focus())
              }}
              aria-label="Clear output"
              title="Clear"
              disabled={busy || !open}
            >
              ⟲
            </button>
            <button type="button" className="iconBtn" onClick={onClose} aria-label="Close" title="Close">
              ✕
            </button>
          </div>
        </header>

        <div
          ref={bodyRef}
          className="sqlTerminalBody"
          style={{ gridTemplateColumns: `${Math.round(splitLeftFraction * 1000)}fr 8px ${Math.round((1 - splitLeftFraction) * 1000)}fr` }}
        >
          <div className="sqlTerminalPane sqlTerminalPaneSql">
            <div className="sqlTerminalPaneTitle mono">
              <div className="sqlTerminalPaneTitleLeft">
                <span>SQL</span>
                <div ref={schemaMenuOpen ? schemaMenuWrapRef : null} className="selectMenuWrap sqlTerminalSchemaMenu">
                  <button
                    type="button"
                    className="selectMenuBtn mono"
                    disabled={!schemas.length || (selectedConn?.type !== 'postgres')}
                    onPointerDown={e => e.stopPropagation()}
                    onClick={e => {
                      e.preventDefault()
                      e.stopPropagation()
                      if (!schemas.length) return
                      setSchemaMenuOpen(v => !v)
                    }}
                    aria-haspopup="menu"
                    aria-expanded={schemaMenuOpen}
                    aria-label="Schema"
                    title="Schema"
                  >
                    {selectedConn?.type !== 'postgres' ? 'Schema' : (selectedSchema || 'Schema')}
                  </button>
                  {schemaMenuOpen ? (
                    <div
                      className="selectMenuPanel"
                      role="menu"
                      onPointerDown={e => {
                        e.preventDefault()
                        e.stopPropagation()
                      }}
                      onClick={e => {
                        e.preventDefault()
                        e.stopPropagation()
                      }}
                    >
                      {schemas.map(s => (
                        <button
                          key={s}
                          type="button"
                          className={`selectMenuItem ${selectedSchema === s ? 'selectMenuItemActive' : ''}`}
                          role="menuitem"
                          onClick={() => {
                            setSchemaMenuOpen(false)
                            setSelectedSchema(s)
                            requestAnimationFrame(() => sqlRef.current?.focus())
                          }}
                        >
                          <span className="mono">{s}</span>
                        </button>
                      ))}
                    </div>
                  ) : null}
                </div>
              </div>
              <button
                type="button"
                className="iconBtn sqlTerminalPlayBtn"
                onClick={() => void run()}
                disabled={busy || !open || !selectedConn || !sql.trim()}
                aria-label="Run SQL"
                title={busy ? 'Running…' : 'Run (Ctrl+Enter)'}
              >
                ▶
              </button>
            </div>
            <div className="sqlTerminalEditorWrap">
              <textarea
                ref={sqlRef}
                className="sqlTerminalEditor mono"
                value={sql}
                disabled={!open || busy}
                onChange={e => {
                  const nextText = e.target.value
                  const caret = e.target.selectionStart ?? 0

                  const hist = editHistoryRef.current
                  if (!hist.applying) {
                    const current = hist.stack[hist.index]?.text ?? ''
                    if (current !== nextText) {
                      const nextEntry = { text: nextText, caret }
                      const base = hist.stack.slice(0, hist.index + 1)
                      const nextStack = clampHistory([...base, nextEntry], 20)
                      const nextIndex = nextStack.length - 1
                      editHistoryRef.current = { stack: nextStack, index: nextIndex, applying: false }
                    }
                  }

                  setSql(nextText)
                  requestAnimationFrame(() => setCursorPos(sqlRef.current?.selectionStart ?? 0))
                }}
                onKeyUp={() => setCursorPos(sqlRef.current?.selectionStart ?? 0)}
                onClick={() => setCursorPos(sqlRef.current?.selectionStart ?? 0)}
                onSelect={() => setCursorPos(sqlRef.current?.selectionStart ?? 0)}
                onKeyDown={e => {
                  const isUndo = (e.ctrlKey && !e.shiftKey && !e.metaKey && e.key.toLowerCase() === 'z') || (e.metaKey && !e.shiftKey && e.key.toLowerCase() === 'z')
                  const isRedo =
                    (e.ctrlKey && !e.shiftKey && !e.metaKey && e.key.toLowerCase() === 'y') ||
                    (e.metaKey && e.shiftKey && e.key.toLowerCase() === 'z') ||
                    (e.ctrlKey && e.shiftKey && e.key.toLowerCase() === 'z')

                  if (isUndo) {
                    e.preventDefault()
                    e.stopPropagation()
                    const hist = editHistoryRef.current
                    if (hist.index > 0) {
                      const nextIndex = hist.index - 1
                      const entry = hist.stack[nextIndex]
                      editHistoryRef.current = { ...hist, index: nextIndex, applying: true }
                      pendingCaretRef.current = entry.caret
                      setSql(entry.text)
                      requestAnimationFrame(() => {
                        const h = editHistoryRef.current
                        editHistoryRef.current = { ...h, applying: false }
                      })
                    }
                    return
                  }

                  if (isRedo) {
                    e.preventDefault()
                    e.stopPropagation()
                    const hist = editHistoryRef.current
                    if (hist.index < hist.stack.length - 1) {
                      const nextIndex = hist.index + 1
                      const entry = hist.stack[nextIndex]
                      editHistoryRef.current = { ...hist, index: nextIndex, applying: true }
                      pendingCaretRef.current = entry.caret
                      setSql(entry.text)
                      requestAnimationFrame(() => {
                        const h = editHistoryRef.current
                        editHistoryRef.current = { ...h, applying: false }
                      })
                    }
                    return
                  }

                  if ((e.ctrlKey || e.metaKey) && e.key === 'Enter') {
                    e.preventDefault()
                    e.stopPropagation()
                    void run()
                  }
                }}
                placeholder={connOptions.length ? 'Write SQL here… (Ctrl+Enter to run)' : 'Configure DB connection in Environment settings…'}
                spellCheck={false}
              />

              {open && tableSuggestOpen && tableSuggestReplaceRange ? (
                <div
                  className="sqlTerminalTableSuggest selectMenuPanel"
                  role="listbox"
                  onPointerDown={e => {
                    e.preventDefault()
                    e.stopPropagation()
                  }}
                  onClick={e => {
                    e.preventDefault()
                    e.stopPropagation()
                  }}
                >
                  {suggestMode === 'column' ? (
                    columnSuggestions.length ? (
                      columnSuggestions.map(c => (
                        <button
                          key={c}
                          type="button"
                          className="selectMenuItem"
                          role="option"
                          onClick={() => {
                            const range = tableSuggestReplaceRange
                            if (!range) return
                            const next = `${sql.slice(0, range.start)}${c}${sql.slice(range.end)}`
                            setSql(next)
                            setTableSuggestOpen(false)
                            requestAnimationFrame(() => {
                              const ta = sqlRef.current
                              if (!ta) return
                              const newPos = range.start + c.length
                              ta.focus()
                              ta.selectionStart = newPos
                              ta.selectionEnd = newPos
                              setCursorPos(newPos)
                            })
                          }}
                        >
                          <span className="mono">{c}</span>
                        </button>
                      ))
                    ) : (
                      <div className="selectMenuItem" style={{ cursor: 'default', opacity: 0.75 }}>
                        {columnLoading ? 'Loading columns…' : 'No matches'}
                      </div>
                    )
                  ) : (
                    tableSuggestions.length ? (
                      tableSuggestions.map(t => (
                        <button
                          key={t}
                          type="button"
                          className="selectMenuItem"
                          role="option"
                          onClick={() => {
                            const range = tableSuggestReplaceRange
                            if (!range) return
                            const needsLeadingSpace = /(from|into)$/i.test(sql.slice(0, range.start))
                            const tableRef = tableSuggestKind === 'from' ? `${t} ${makeTableAlias(t)}` : t
                            const insert = `${needsLeadingSpace ? ' ' : ''}${tableRef}`
                            const next = `${sql.slice(0, range.start)}${insert}${sql.slice(range.end)}`
                            setSql(next)
                            setTableSuggestOpen(false)
                            requestAnimationFrame(() => {
                              const ta = sqlRef.current
                              if (!ta) return
                              const newPos = range.start + insert.length
                              ta.focus()
                              ta.selectionStart = newPos
                              ta.selectionEnd = newPos
                              setCursorPos(newPos)
                            })
                          }}
                        >
                          <span className="mono">{t}</span>
                        </button>
                      ))
                    ) : (
                      <div className="selectMenuItem" style={{ cursor: 'default', opacity: 0.75 }}>
                        No matches
                      </div>
                    )
                  )}
                </div>
              ) : null}
            </div>
          </div>
          <div className="sqlTerminalDivider" onPointerDown={onSplitHandlePointerDown} />
          <div className="sqlTerminalPane">
            <div className="sqlTerminalPaneTitle mono">
              <span>Output</span>
              {resultHint ? <span style={{ opacity: 0.75 }}>{resultHint}</span> : null}
            </div>
            <div
              ref={outputRef}
              className="sqlTerminalOutput mono"
              role="log"
              aria-live="polite"
              onPointerDown={() => sqlRef.current?.focus()}
            >
              {effectiveResultColumns.length ? (
                <div className="sqlTerminalTableWrap">
                  <table className="sqlTerminalTable">
                    <thead>
                      <tr>
                        {effectiveResultColumns.map(c => (
                          <th key={c} className="mono" title={c}>
                            {c}
                          </th>
                        ))}
                      </tr>
                    </thead>
                    <tbody>
                      {(resultRows ?? []).slice(0, 500).map((row, idx) => (
                        <tr key={idx}>
                          {effectiveResultColumns.map(c => {
                            const v = (row as Record<string, unknown>)[c]
                            const text = v == null ? '' : typeof v === 'string' ? v : JSON.stringify(v)
                            return (
                              <td key={c} title={text}>
                                {text}
                              </td>
                            )
                          })}
                        </tr>
                      ))}
                    </tbody>
                  </table>
                  {(resultRows?.length ?? 0) > 500 ? (
                    <div className="terminalLine terminalLine_sys" style={{ marginTop: 8 }}>
                      Showing first 500 rows.
                    </div>
                  ) : null}
                </div>
              ) : output.length ? (
                output.map((e, i) => (
                  <div key={i} className={`terminalLine terminalLine_${e.kind}`}>
                    {e.text}
                  </div>
                ))
              ) : (
                <div className="terminalLine terminalLine_sys">Run a query to see output.</div>
              )}
            </div>
          </div>
        </div>
      </section>
    </>
  )
}

import { forwardRef, useEffect, useMemo, useRef, useState, type InputHTMLAttributes, type TextareaHTMLAttributes } from 'react'
import type { VariableSuggestion } from '../utils/variables'

type BaseProps = {
  value: string
  onChangeValue: (next: string) => void
  suggestions: VariableSuggestion[]
}

type InputProps = BaseProps & {
  as?: 'input'
} & Omit<InputHTMLAttributes<HTMLInputElement>, 'value' | 'onChange'>

type TextareaProps = BaseProps & {
  as: 'textarea'
} & Omit<TextareaHTMLAttributes<HTMLTextAreaElement>, 'value' | 'onChange'>

type Props = InputProps | TextareaProps

type PendingSelection = { start: number, end: number }

function computeToken(value: string, cursor: number): { start: number, query: string } | null {
  const before = value.slice(0, cursor)
  const start = before.lastIndexOf('{{')
  if (start < 0) return null
  const closeIdx = before.indexOf('}}', start + 2)
  if (closeIdx >= 0) return null
  return { start, query: before.slice(start + 2) }
}

function clamp(n: number, min: number, max: number): number {
  return Math.max(min, Math.min(max, n))
}

function getCaretAnchorRect(
  el: HTMLInputElement | HTMLTextAreaElement,
  cursor: number,
  mirrorEl: HTMLDivElement,
): DOMRect | null {
  try {
    const cs = window.getComputedStyle(el)
    const isTextarea = el.tagName.toLowerCase() === 'textarea'

    const rect = el.getBoundingClientRect()
    mirrorEl.style.position = 'fixed'
    mirrorEl.style.left = `${Math.round(rect.left)}px`
    mirrorEl.style.top = `${Math.round(rect.top)}px`
    mirrorEl.style.width = `${Math.round(rect.width)}px`
    mirrorEl.style.height = `${Math.round(rect.height)}px`
    mirrorEl.style.visibility = 'hidden'
    mirrorEl.style.pointerEvents = 'none'
    mirrorEl.style.overflow = 'hidden'
    mirrorEl.style.whiteSpace = isTextarea ? 'pre-wrap' : 'pre'
    mirrorEl.style.wordWrap = 'break-word'
    mirrorEl.style.overflowWrap = 'break-word'
    mirrorEl.style.boxSizing = cs.boxSizing
    mirrorEl.style.border = cs.border
    mirrorEl.style.padding = cs.padding
    mirrorEl.style.font = cs.font
    mirrorEl.style.letterSpacing = cs.letterSpacing
    mirrorEl.style.textTransform = cs.textTransform
    mirrorEl.style.textIndent = cs.textIndent
    mirrorEl.style.lineHeight = cs.lineHeight
    mirrorEl.style.tabSize = (cs as any).tabSize ?? '4'

    const before = el.value.slice(0, cursor)
    const after = el.value.slice(cursor) || '\u200b'

    mirrorEl.textContent = ''
    const beforeSpan = document.createElement('span')
    beforeSpan.textContent = before
    const caretSpan = document.createElement('span')
    caretSpan.textContent = '\u200b'
    const afterSpan = document.createElement('span')
    afterSpan.textContent = after
    mirrorEl.appendChild(beforeSpan)
    mirrorEl.appendChild(caretSpan)
    mirrorEl.appendChild(afterSpan)

    mirrorEl.scrollTop = (el as HTMLTextAreaElement).scrollTop ?? 0
    mirrorEl.scrollLeft = (el as HTMLTextAreaElement).scrollLeft ?? 0

    const caretRect = caretSpan.getBoundingClientRect()
    return caretRect
  } catch {
    return null
  }
}

export const VariableAutocompleteField = forwardRef<HTMLInputElement | HTMLTextAreaElement, Props>(
  function VariableAutocompleteField(props, forwardedRef) {
    const { as: asProp, value, onChangeValue, suggestions, onBlur, onKeyDown, onClick, onFocus, onKeyUp, ...rest } = props
    const as = asProp ?? 'input'
    const { className, style, ...restProps } = rest

    const rootRef = useRef<HTMLDivElement | null>(null)
    const inputRef = useRef<HTMLInputElement | HTMLTextAreaElement | null>(null)
    const menuPanelRef = useRef<HTMLDivElement | null>(null)
    const mirrorRef = useRef<HTMLDivElement | null>(null)
    const lastCursorRef = useRef<number>(0)
    const setRefs = (el: HTMLInputElement | HTMLTextAreaElement | null) => {
      inputRef.current = el
      if (typeof forwardedRef === 'function') forwardedRef(el)
      else if (forwardedRef) (forwardedRef as any).current = el
    }

    const pendingSelectionRef = useRef<PendingSelection | null>(null)
    const [menuOpen, setMenuOpen] = useState(false)
    const [anchor, setAnchor] = useState<{ left: number, top: number, width: number, caretTop: number, caretBottom: number }>({
      left: 0,
      top: 0,
      width: 320,
      caretTop: 0,
      caretBottom: 0,
    })
    const [query, setQuery] = useState('')
    const [activeIndex, setActiveIndex] = useState(0)

    const filtered = useMemo(() => {
      const needle = query.trim().toLowerCase()
      const items = needle
        ? suggestions.filter(s => s.name.toLowerCase().includes(needle))
        : suggestions
      return items
    }, [query, suggestions])

    function ensureMirrorEl(): HTMLDivElement {
      if (mirrorRef.current) return mirrorRef.current
      const div = document.createElement('div')
      div.setAttribute('data-var-mirror', '1')
      document.body.appendChild(div)
      mirrorRef.current = div
      return div
    }

    function updateAnchorFromEl(el: HTMLInputElement | HTMLTextAreaElement, cursor: number) {
      const r = el.getBoundingClientRect()
      const mirrorEl = ensureMirrorEl()
      const caretRect = getCaretAnchorRect(el, cursor, mirrorEl)
      const baseRect = caretRect ?? r

      const margin = 8
      const maxWidth = Math.max(220, window.innerWidth - margin * 2)
      const width = clamp(320, 220, maxWidth)
      const left = clamp(Math.round(baseRect.left), margin, Math.max(margin, window.innerWidth - width - margin))
      const caretTop = Math.round(baseRect.top)
      const caretBottom = Math.round(baseRect.bottom)
      const desiredTop = Math.round(baseRect.bottom + 6)
      const top = clamp(desiredTop, margin, Math.max(margin, window.innerHeight - margin))

      setAnchor({ left, top, width, caretTop, caretBottom })
    }

    function updateMenuFromEl(el: HTMLInputElement | HTMLTextAreaElement, nextValue: string) {
      const cursor = el.selectionStart ?? nextValue.length
      lastCursorRef.current = cursor
      const token = computeToken(nextValue, cursor)
      if (!token) {
        setMenuOpen(false)
        setQuery('')
        return
      }

      updateAnchorFromEl(el, cursor)
      setQuery(token.query)
      setActiveIndex(0)
      setMenuOpen(true)
    }

    function applySuggestion(name: string) {
      const el = inputRef.current
      if (!el) return
      const cursor = el.selectionStart ?? value.length
      const token = computeToken(value, cursor)
      if (!token) return

      const after = value.slice(cursor)
      const hasClosing = after.startsWith('}}')
      const insert = hasClosing ? `{{${name}` : `{{${name}}}`
      const nextValue = value.slice(0, token.start) + insert + after
      const nextCursor = token.start + insert.length + (hasClosing ? 2 : 0)

      pendingSelectionRef.current = { start: nextCursor, end: nextCursor }
      setMenuOpen(false)
      setQuery('')
      onChangeValue(nextValue)
    }

    useEffect(() => {
      const pending = pendingSelectionRef.current
      if (!pending) return
      const el = inputRef.current
      if (!el) return
      pendingSelectionRef.current = null
      try {
        el.setSelectionRange(pending.start, pending.end)
      } catch {
        // ignore
      }
    }, [value])

    useEffect(() => {
      if (!menuOpen) return

      function onPointerDown(e: PointerEvent) {
        const t = e.target as Node | null
        const wrap = rootRef.current
        if (t && wrap && wrap.contains(t)) return
        setMenuOpen(false)
      }

      function onGlobalScrollOrResize() {
        const el = inputRef.current
        if (!el) return
        updateAnchorFromEl(el, lastCursorRef.current)
      }

      window.addEventListener('pointerdown', onPointerDown)
      window.addEventListener('scroll', onGlobalScrollOrResize, true)
      window.addEventListener('resize', onGlobalScrollOrResize)
      return () => {
        window.removeEventListener('pointerdown', onPointerDown)
        window.removeEventListener('scroll', onGlobalScrollOrResize, true)
        window.removeEventListener('resize', onGlobalScrollOrResize)
      }
    }, [menuOpen])

    useEffect(() => {
      return () => {
        const m = mirrorRef.current
        mirrorRef.current = null
        if (m && m.parentNode) m.parentNode.removeChild(m)
      }
    }, [])

    useEffect(() => {
      if (!menuOpen) return
      const panel = menuPanelRef.current
      if (!panel) return
      const el = panel.querySelector<HTMLElement>(`[data-var-idx="${activeIndex}"]`)
      if (!el) return
      try {
        el.scrollIntoView({ block: 'nearest' })
      } catch {
        // ignore
      }
    }, [activeIndex, menuOpen])

    useEffect(() => {
      if (!menuOpen) return
      const panel = menuPanelRef.current
      if (!panel) return

      const margin = 8
      const rect = panel.getBoundingClientRect()

      let nextLeft = anchor.left
      let nextTop = anchor.top

      if (rect.right > window.innerWidth - margin) nextLeft = Math.max(margin, window.innerWidth - margin - rect.width)
      if (rect.left < margin) nextLeft = margin

      const overflowBottom = rect.bottom - (window.innerHeight - margin)
      if (overflowBottom > 0) {
        const aboveTop = anchor.caretTop - 6 - rect.height
        if (aboveTop >= margin) nextTop = aboveTop
        else nextTop = Math.max(margin, window.innerHeight - margin - rect.height)
      }
      if (rect.top < margin) nextTop = margin

      if (nextLeft !== anchor.left || nextTop !== anchor.top) {
        setAnchor(prev => {
          if (prev.left === nextLeft && prev.top === nextTop) return prev
          return { ...prev, left: nextLeft, top: nextTop }
        })
      }
    }, [anchor.left, anchor.top, anchor.caretTop, menuOpen])

    const commonHandlers = {
      ref: setRefs as any,
      value,
      onChange: (e: any) => {
        const next = String(e.target.value ?? '')
        onChangeValue(next)
        updateMenuFromEl(e.target, next)
      },
      onFocus: (e: any) => {
        onFocus?.(e)
        updateMenuFromEl(e.target, String(e.target.value ?? ''))
      },
      onClick: (e: any) => {
        onClick?.(e)
        updateMenuFromEl(e.target, String(e.target.value ?? ''))
      },
      onKeyUp: (e: any) => {
        onKeyUp?.(e)
        if (
          e?.key === 'ArrowDown' ||
          e?.key === 'ArrowUp' ||
          e?.key === 'Enter' ||
          e?.key === 'Tab' ||
          e?.key === 'Escape'
        ) return
        updateMenuFromEl(e.target, String(e.target.value ?? ''))
      },
      onKeyDown: (e: any) => {
        if (menuOpen) {
          if (e.key === 'Escape') {
            e.preventDefault()
            e.stopPropagation()
            setMenuOpen(false)
            return
          }
          if (e.key === 'ArrowDown') {
            e.preventDefault()
            e.stopPropagation()
            setActiveIndex(i => (filtered.length ? (i + 1) % filtered.length : 0))
            return
          }
          if (e.key === 'ArrowUp') {
            e.preventDefault()
            e.stopPropagation()
            setActiveIndex(i => (filtered.length ? (i - 1 + filtered.length) % filtered.length : 0))
            return
          }
          if (e.key === 'Enter' || e.key === 'Tab') {
            const picked = filtered[activeIndex]
            if (picked) {
              e.preventDefault()
              e.stopPropagation()
              applySuggestion(picked.name)
              return
            }
          }
        }

        onKeyDown?.(e)
      },
      onBlur: (e: any) => {
        const currentValue = String((e?.target as HTMLInputElement | HTMLTextAreaElement | null)?.value ?? '')
        if (currentValue !== value) onChangeValue(currentValue)
        onBlur?.(e)
        setTimeout(() => setMenuOpen(false), 0)
      },
    }

    return (
      <div ref={rootRef} style={{ position: 'relative', width: '100%', ...(style as any) }}>
        {as === 'textarea' ? (
          <textarea
            {...(restProps as TextareaHTMLAttributes<HTMLTextAreaElement>)}
            {...commonHandlers}
            className={className}
            style={{ width: '100%' }}
          />
        ) : (
          <input
            {...(restProps as InputHTMLAttributes<HTMLInputElement>)}
            {...commonHandlers}
            className={className}
            style={{ width: '100%' }}
          />
        )}

        {menuOpen ? (
          <div
            className="selectMenuPanel varMenuPanel"
            ref={menuPanelRef}
            role="menu"
            style={{ position: 'fixed', left: anchor.left, top: anchor.top, width: anchor.width, zIndex: 200 }}
            onPointerDown={e => {
              e.preventDefault()
              e.stopPropagation()
            }}
            onClick={e => {
              e.preventDefault()
              e.stopPropagation()
            }}
          >
            {filtered.length ? (
              filtered.map((s, idx) => (
                <button
                  key={`${s.kind}:${s.name}`}
                  type="button"
                  className={`selectMenuItem ${idx === activeIndex ? 'selectMenuItemActive' : ''}`}
                  role="menuitem"
                  data-var-idx={idx}
                  onClick={() => applySuggestion(s.name)}
                >
                  <div className="varMenuItem">
                    <div className="mono">{s.name}</div>
                    {s.description ? <div className="varMenuDesc">{s.description}</div> : null}
                  </div>
                </button>
              ))
            ) : (
              <div className="varMenuEmpty small">No variables</div>
            )}
          </div>
        ) : null}
      </div>
    )
  },
)

import { isTauri } from './tauri'
import { tauriInvoke } from './tauri'

function getUrlString(input: RequestInfo | URL): string | null {
  if (typeof input === 'string') return input
  if (input instanceof URL) return input.toString()
  if (input instanceof Request) return input.url
  return null
}

function normalizeHttpUrlLoose(url: string): string | null {
  const raw = url.trim()
  if (!raw) return null

  try {
    const u = new URL(raw)
    if (u.protocol === 'http:' || u.protocol === 'https:') return u.toString()
    return null
  } catch {
    // tolerate common typo: "http:/host/..." or "https:/host/..."
    const fixed = raw.replace(/^https?:\/(?!\/)/i, m => `${m}/`)
    try {
      const u = new URL(fixed)
      if (u.protocol === 'http:' || u.protocol === 'https:') return u.toString()
      return null
    } catch {
      return null
    }
  }
}

function toBase64(bytes: Uint8Array): string {
  let s = ''
  for (let i = 0; i < bytes.length; i++) s += String.fromCharCode(bytes[i])
  return btoa(s)
}

async function bodyToBase64(body: BodyInit): Promise<{ bodyBase64: string; contentType?: string }> {
  if (typeof body === 'string') {
    const bytes = new TextEncoder().encode(body)
    return { bodyBase64: toBase64(bytes) }
  }

  if (body instanceof URLSearchParams) {
    const bytes = new TextEncoder().encode(body.toString())
    return { bodyBase64: toBase64(bytes), contentType: 'application/x-www-form-urlencoded;charset=UTF-8' }
  }

  if (body instanceof Blob) {
    const buf = await body.arrayBuffer()
    return { bodyBase64: toBase64(new Uint8Array(buf)), contentType: body.type || undefined }
  }

  if (body instanceof ArrayBuffer) {
    return { bodyBase64: toBase64(new Uint8Array(body)) }
  }

  if (ArrayBuffer.isView(body)) {
    const bytes = new Uint8Array(body.buffer, body.byteOffset, body.byteLength)
    return { bodyBase64: toBase64(bytes) }
  }

  if (body instanceof FormData) {
    const boundary = `ruf-${Math.random().toString(16).slice(2)}${Date.now().toString(16)}`
    const encoder = new TextEncoder()
    const chunks: Uint8Array[] = []

    for (const [key, value] of body.entries()) {
      chunks.push(encoder.encode(`--${boundary}\r\n`))
      if (typeof value === 'string') {
        chunks.push(encoder.encode(`Content-Disposition: form-data; name="${key}"\r\n\r\n`))
        chunks.push(encoder.encode(value))
        chunks.push(encoder.encode('\r\n'))
      } else {
        const fileName = (value as File).name || 'blob'
        const contentType = value.type || 'application/octet-stream'
        chunks.push(
          encoder.encode(
            `Content-Disposition: form-data; name="${key}"; filename="${fileName}"\r\n` +
              `Content-Type: ${contentType}\r\n\r\n`,
          ),
        )
        const buf = await value.arrayBuffer()
        chunks.push(new Uint8Array(buf))
        chunks.push(encoder.encode('\r\n'))
      }
    }

    chunks.push(encoder.encode(`--${boundary}--\r\n`))

    let total = 0
    for (const c of chunks) total += c.byteLength
    const out = new Uint8Array(total)
    let offset = 0
    for (const c of chunks) {
      out.set(c, offset)
      offset += c.byteLength
    }

    return { bodyBase64: toBase64(out), contentType: `multipart/form-data; boundary=${boundary}` }
  }

  throw new Error('Unsupported request body type in desktop backend transport')
}

export async function platformFetch(
  input: RequestInfo | URL,
  init?: RequestInit,
  opts?: { insecureTls?: boolean; caCertsPem?: string[] },
): Promise<Response> {
  const signal = init?.signal
  if (signal?.aborted) {
    throw new DOMException('Aborted', 'AbortError')
  }

  if (isTauri()) {
    const urlString = getUrlString(input)
    const normalizedNetworkUrl = urlString ? normalizeHttpUrlLoose(urlString) : null
    const isNetworkUrl = !!normalizedNetworkUrl

    try {
      if (normalizedNetworkUrl) {
        const url = normalizedNetworkUrl
        const method = (init?.method || 'GET').toUpperCase()

        const headers: [string, string][] = []
        const h = init?.headers
        if (h instanceof Headers) {
          h.forEach((v, k) => headers.push([k, v]))
        } else if (Array.isArray(h)) {
          for (const [k, v] of h) headers.push([k, String(v)])
        } else if (h && typeof h === 'object') {
          for (const [k, v] of Object.entries(h)) headers.push([k, String(v)])
        }

        const body = init?.body ?? null
        let bodyBase64: string | undefined
        let inferredContentType: string | undefined
        if (body !== null) {
          const encoded = await bodyToBase64(body)
          bodyBase64 = encoded.bodyBase64
          inferredContentType = encoded.contentType
        }

        if (inferredContentType) {
          const hasContentType = headers.some(([k]) => k.toLowerCase() === 'content-type')
          if (!hasContentType) headers.push(['Content-Type', inferredContentType])
        }

        type HttpRequestResult = {
          ok: boolean
          status: number
          statusText: string
          headers: [string, string][]
          bodyBase64: string
        }

        const requestPromise = tauriInvoke<HttpRequestResult>('http_request', {
          args: {
            url,
            method,
            headers,
            bodyBase64,
            insecureTls: !!opts?.insecureTls,
            caCertsPem: opts?.caCertsPem,
          },
        })

        const result: HttpRequestResult = await (signal
          ? new Promise<HttpRequestResult>((resolve, reject) => {
            let settled = false
            const onAbort = () => {
              if (settled) return
              settled = true
              reject(new DOMException('Aborted', 'AbortError'))
            }
            signal.addEventListener('abort', onAbort, { once: true })
            requestPromise.then(
              v => {
                if (settled) return
                settled = true
                signal.removeEventListener('abort', onAbort)
                resolve(v)
              },
              err => {
                if (settled) return
                settled = true
                signal.removeEventListener('abort', onAbort)
                reject(err)
              },
            )
          })
          : requestPromise)

        const binary = atob(result.bodyBase64 || '')
        const bytes = new Uint8Array(binary.length)
        for (let i = 0; i < binary.length; i++) bytes[i] = binary.charCodeAt(i)

        return new Response(bytes, {
          status: result.status,
          statusText: result.statusText || '',
          headers: new Headers(result.headers || []),
        })
      }
    } catch (e: any) {
      if (isNetworkUrl) {
        if (e?.name === 'AbortError') throw e
        const msg = e?.message ? String(e.message) : String(e)
        throw new Error(`Backend http_request failed: ${msg}`)
      }
    }
  }

  return await globalThis.fetch(input, init)
}

import type { RequestHistoryItem } from '../types/requestHistory'

const REQUEST_HISTORY_KEY = 'ruf_request_history_v1'

function safeParseJson<T>(raw: string | null): T | null {
  try {
    if (!raw) return null
    return JSON.parse(raw) as T
  } catch {
    return null
  }
}

function isRecord(x: unknown): x is Record<string, unknown> {
  return !!x && typeof x === 'object' && !Array.isArray(x)
}

function normalizeHistoryItem(raw: unknown): RequestHistoryItem | null {
  if (!isRecord(raw)) return null
  const id = typeof raw.id === 'string' ? raw.id : ''
  const createdAt = typeof raw.createdAt === 'number' ? raw.createdAt : 0
  const method = typeof raw.method === 'string' ? (raw.method as any) : ''
  const url = typeof raw.url === 'string' ? raw.url : ''
  const draft = isRecord(raw.draft) ? (raw.draft as any) : {}
  if (!id || !createdAt || !method || !url) return null
  return { id, createdAt, method, url, draft }
}

export function loadRequestHistoryByRequestId(): Record<string, RequestHistoryItem[]> {
  const parsed = safeParseJson<unknown>(localStorage.getItem(REQUEST_HISTORY_KEY))
  if (!isRecord(parsed)) return {}

  const out: Record<string, RequestHistoryItem[]> = {}
  for (const [requestId, arr] of Object.entries(parsed)) {
    if (typeof requestId !== 'string' || !requestId) continue
    if (!Array.isArray(arr)) continue
    const items: RequestHistoryItem[] = []
    for (const rawItem of arr) {
      const item = normalizeHistoryItem(rawItem)
      if (item) items.push(item)
    }
    if (items.length) out[requestId] = items
  }
  return out
}

export function saveRequestHistoryByRequestId(history: Record<string, RequestHistoryItem[]>) {
  localStorage.setItem(REQUEST_HISTORY_KEY, JSON.stringify(history))
}

export function appendRequestHistoryItem(args: {
  historyByRequestId: Record<string, RequestHistoryItem[]>
  requestId: string
  item: RequestHistoryItem
  maxItemsPerRequest?: number
}): Record<string, RequestHistoryItem[]> {
  const maxItemsPerRequest = args.maxItemsPerRequest ?? 30
  const prevItems = args.historyByRequestId[args.requestId] ?? []
  const nextItems = [args.item, ...prevItems].slice(0, Math.max(1, maxItemsPerRequest))
  return { ...args.historyByRequestId, [args.requestId]: nextItems }
}

import type { Collection } from '../../modules/collectionTree'
import type { Environment } from '../types/environment'

const COLLECTIONS_KEY = 'ruf_collections_v1'
const ENVS_BY_COLLECTION_KEY = 'ruf_env_by_collection_v1'

export function loadCollections(): Collection[] {
  try {
    const raw = localStorage.getItem(COLLECTIONS_KEY)
    if (!raw) return []
    return JSON.parse(raw) as Collection[]
  } catch {
    return []
  }
}

export function saveCollections(cols: Collection[]) {
  localStorage.setItem(COLLECTIONS_KEY, JSON.stringify(cols))
}

export function loadEnvironmentsByCollection(): Record<string, Environment> {
  try {
    const raw = localStorage.getItem(ENVS_BY_COLLECTION_KEY)
    if (!raw) return {}
    const parsed = JSON.parse(raw) as any
    if (!parsed || typeof parsed !== 'object') return {}

    const out: Record<string, Environment> = {}
    for (const [id, env] of Object.entries(parsed)) {
      if (typeof id !== 'string' || !id) continue
      const baseUrlKey = typeof (env as any)?.baseUrlKey === 'string' && (env as any).baseUrlKey.trim()
        ? (env as any).baseUrlKey.trim()
        : 'baseUrl'

      const varsObj = (env as any)?.variables && typeof (env as any).variables === 'object' ? (env as any).variables : {}
      const variables: Record<string, string> = {}
      for (const [k, v] of Object.entries(varsObj)) {
        if (typeof k === 'string' && k.trim() && typeof v === 'string') variables[k.trim()] = v
      }

      // backward-compat: old env schema stored { baseUrl, headers }
      const legacyBaseUrl = typeof (env as any)?.baseUrl === 'string' ? (env as any).baseUrl : ''
      if (!variables[baseUrlKey] && legacyBaseUrl) variables[baseUrlKey] = legacyBaseUrl
      if (!variables[baseUrlKey]) variables[baseUrlKey] = ''
      if (typeof variables.scheme !== 'string' || !variables.scheme.trim()) variables.scheme = 'http'

      const headersObj = (env as any)?.headers && typeof (env as any).headers === 'object' ? (env as any).headers : {}
      const headers: Record<string, string> = {}
      for (const [k, v] of Object.entries(headersObj)) {
        if (typeof k === 'string' && typeof v === 'string' && k.trim()) headers[k] = v
      }
      out[id] = { baseUrlKey, variables, headers }
    }
    return out
  } catch {
    return {}
  }
}

export function saveEnvironmentsByCollection(envs: Record<string, Environment>) {
  localStorage.setItem(ENVS_BY_COLLECTION_KEY, JSON.stringify(envs))
}

import { defineConfig } from 'vite'
import react from '@vitejs/plugin-react'
import * as http from 'node:http'
import * as https from 'node:https'

async function fetchViaNodeHttp(args: {
  url: URL
  method: string
  headers: Record<string, string>
  body?: Buffer
  insecureTls: boolean
}): Promise<{ status: number, headers: Record<string, string>, body: Buffer }> {
  const u = args.url
  const isHttps = u.protocol === 'https:'
  const transport = isHttps ? https : http

  return await new Promise((resolve, reject) => {
    const req = transport.request({
      protocol: u.protocol,
      hostname: u.hostname,
      port: u.port ? Number(u.port) : (isHttps ? 443 : 80),
      path: `${u.pathname}${u.search}`,
      method: args.method,
      headers: args.headers,
      ...(isHttps ? { rejectUnauthorized: !args.insecureTls } : {}),
    }, (resp) => {
      const chunks: Buffer[] = []
      resp.on('data', (c: Buffer) => chunks.push(c))
      resp.on('end', () => {
        const headers: Record<string, string> = {}
        for (const [k, v] of Object.entries(resp.headers)) {
          if (v === undefined) continue
          if (Array.isArray(v)) headers[k] = v.join(',')
          else headers[k] = String(v)
        }
        resolve({
          status: resp.statusCode ?? 0,
          headers,
          body: Buffer.concat(chunks),
        })
      })
    })
    req.on('error', reject)
    if (args.body && args.body.length) req.write(args.body)
    req.end()
  })
}

async function registerProxyRoute(middlewares: any) {
  middlewares.use('/__ruf_proxy', async (req: any, res: any) => {
    try {
      const rawUrl = req.url || ''
      const full = new URL(rawUrl, 'http://localhost')
      const target = full.searchParams.get('url') || ''
      if (!target) {
        res.statusCode = 400
        res.setHeader('Content-Type', 'text/plain; charset=utf-8')
        res.end('Missing ?url=')
        return
      }

      const insecure = ['1', 'true', 'yes'].includes((full.searchParams.get('insecure') || '').toLowerCase())

      let u: URL
      try {
        u = new URL(target)
      } catch {
        res.statusCode = 400
        res.setHeader('Content-Type', 'text/plain; charset=utf-8')
        res.end('Invalid url')
        return
      }

      if (u.protocol !== 'http:' && u.protocol !== 'https:') {
        res.statusCode = 400
        res.setHeader('Content-Type', 'text/plain; charset=utf-8')
        res.end('Only http/https supported')
        return
      }

      const headers = new Headers()
      for (const [k, v] of Object.entries(req.headers)) {
        if (v === undefined) continue
        const key = k.toLowerCase()
        if (key === 'host' || key === 'origin' || key === 'referer' || key === 'content-length') continue
        if (Array.isArray(v)) headers.set(k, v.join(','))
        else headers.set(k, v as any)
      }

      const method = (req.method || 'GET').toUpperCase()
      const hasBody = method !== 'GET' && method !== 'HEAD'
      const body = hasBody ? await new Promise<Buffer>((resolve, reject) => {
        const chunks: Buffer[] = []
        req.on('data', (c: Buffer) => chunks.push(c))
        req.on('end', () => resolve(Buffer.concat(chunks)))
        req.on('error', reject)
      }) : undefined

      const proxied = await fetchViaNodeHttp({
        url: u,
        method,
        headers: Object.fromEntries(headers.entries()),
        body: body && body.length ? body : undefined,
        insecureTls: insecure && u.protocol === 'https:',
      })

      res.statusCode = proxied.status
      for (const [k, v] of Object.entries(proxied.headers)) {
        const key = k.toLowerCase()
        if (key === 'transfer-encoding') continue
        res.setHeader(k, v)
      }

      res.end(proxied.body)
    } catch (e: any) {
      res.statusCode = 502
      res.setHeader('Content-Type', 'text/plain; charset=utf-8')
      res.end(e?.message || 'Proxy error')
    }
  })
}

// https://vite.dev/config/
export default defineConfig({
  server: {
    host: '127.0.0.1',
    port: 5173,
    strictPort: true,
  },
  plugins: [
    react(),
    {
      name: 'ruf-dev-proxy',
      configureServer(server) {
        void registerProxyRoute(server.middlewares)
      },
      configurePreviewServer(server) {
        void registerProxyRoute(server.middlewares)
      },
    },
  ],
})
